files.scripts/voice.mjs:
// Buat suara narasi untuk tiap adegan, lalu catat file-nya di src/video.json.
// Mesin suara (pilih di aplikasi → video.json "voice.engine", atau env VOICE_ENGINE):
//   piper      : BAWAAN. Gratis & offline, tanpa API key. Program + model suara diunduh otomatis sekali (±80 MB).
//   elevenlabs : ELEVENLABS_API_KEY di .env (paling natural, waktu kata akurat).
//   openai     : OPENAI_API_KEY di .env (waktu kata dari transkripsi Whisper).
//   none       : tanpa suara (subtitle tetap ada).
// Nada suara (laki-laki/perempuan) diatur di video.json "voice.pitch" dan diterapkan saat render.
import { spawn, spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { chmodSync, existsSync, mkdirSync, readdirSync, readFileSync, renameSync, rmSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";

// Baca .env sederhana (KEY=VALUE per baris).
if (existsSync(".env")) {
  for (const line of readFileSync(".env", "utf8").split(/\r?\n/)) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
    if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
  }
}
const env = (k) => (process.env[k] || "").trim();

// Lokasi storyboard & folder public bisa diganti (dipakai render dari aplikasi: satu folder per pekerjaan).
const videoPath = process.env.VIDEO_JSON || "src/video.json";
const PUB = process.env.PUBLIC_DIR || "public";
const video = JSON.parse(readFileSync(videoPath, "utf8"));
const lang = /^en/i.test(video.voice?.lang || "") ? "en" : "id";
const gender = video.voice?.gender === "male" ? "male" : "female";

let provider = (env("VOICE_ENGINE") || video.voice?.engine || "piper").toLowerCase();
if (provider === "elevenlabs" && !env("ELEVENLABS_API_KEY")) {
  console.log("[suara] ELEVENLABS_API_KEY belum diisi di .env, pakai Piper (gratis).");
  provider = "piper";
}
if (provider === "openai" && !env("OPENAI_API_KEY")) {
  console.log("[suara] OPENAI_API_KEY belum diisi di .env, pakai Piper (gratis).");
  provider = "piper";
}
if (!["piper", "elevenlabs", "openai"].includes(provider)) {
  console.log("[suara] Suara dimatikan. Video dibuat tanpa suara (subtitle tetap ada).");
  for (const s of video.scenes) {
    delete s.voiceFile;
    delete s.words;
  }
  writeFileSync(videoPath, JSON.stringify(video, null, 2) + "\n");
  process.exit(0);
}

// ---------- Piper (offline) ----------
const PIPER_RELEASE = "https://github.com/rhasspy/piper/releases/download/2023.11.14-2";
const HF = "https://huggingface.co/rhasspy/piper-voices/resolve/main";
/** Model suara Piper per bahasa & jenis kelamin. Bahasa Indonesia hanya punya satu suara; jenis kelamin diatur lewat nada. */
const PIPER_VOICES = {
  id: { female: "id/id_ID/news_tts/medium/id_ID-news_tts-medium", male: "id/id_ID/news_tts/medium/id_ID-news_tts-medium" },
  en: { female: "en/en_US/lessac/medium/en_US-lessac-medium", male: "en/en_US/ryan/medium/en_US-ryan-medium" },
};
const PIPER_DIR = path.resolve(".piper");

function piperAsset() {
  const { platform, arch } = process;
  if (platform === "win32") return "piper_windows_amd64.zip";
  if (platform === "darwin") return arch === "arm64" ? "piper_macos_aarch64.tar.gz" : "piper_macos_x64.tar.gz";
  if (arch === "arm64") return "piper_linux_aarch64.tar.gz";
  if (arch === "arm") return "piper_linux_armv7l.tar.gz";
  return "piper_linux_x86_64.tar.gz";
}

async function download(url, dest, label) {
  console.log(`[suara] Mengunduh ${label} (sekali saja)...`);
  let res;
  try {
    res = await fetch(url);
  } catch (e) {
    const c = e.cause || {};
    throw new Error(`gagal mengunduh ${label}: ${c.code || c.message || e.message}${c.hostname ? ` (${c.hostname})` : ""}`);
  }
  if (!res.ok) throw new Error(`gagal mengunduh ${label} (${res.status} dari ${new URL(res.url || url).hostname})`);
  const tmp = dest + ".part";
  writeFileSync(tmp, Buffer.from(await res.arrayBuffer()));
  renameSync(tmp, dest);
}

async function ensurePiper() {
  if (env("PIPER_BIN")) return env("PIPER_BIN");
  const exe = path.join(PIPER_DIR, "piper", process.platform === "win32" ? "piper.exe" : "piper");
  if (existsSync(exe)) return exe;
  mkdirSync(PIPER_DIR, { recursive: true });
  const asset = piperAsset();
  const file = path.join(PIPER_DIR, asset);
  await download(`${env("PIPER_RELEASE_URL") || PIPER_RELEASE}/${asset}`, file, "program suara Piper");
  // tar bawaan Windows 10+ dan macOS bisa membuka .zip; Linux memakai .tar.gz.
  const r = spawnSync("tar", ["-xf", file, "-C", PIPER_DIR], { stdio: "inherit" });
  if (r.status !== 0 || !existsSync(exe)) throw new Error("gagal membuka program Piper. Ekstrak manual " + asset + " ke folder .piper");
  rmSync(file, { force: true });
  if (process.platform !== "win32") chmodSync(exe, 0o755);
  return exe;
}

async function ensureVoiceModel() {
  if (env("PIPER_MODEL")) return env("PIPER_MODEL");
  const key = PIPER_VOICES[lang][gender];
  const base = path.basename(key);
  const dir = path.join(PIPER_DIR, "voices");
  const onnx = path.join(dir, base + ".onnx");
  mkdirSync(dir, { recursive: true });
  const src = env("PIPER_VOICE_BASE_URL") || HF;
  if (!existsSync(onnx + ".json")) await download(`${src}/${key}.onnx.json`, onnx + ".json", "pengaturan suara");
  if (!existsSync(onnx) || statSync(onnx).size < 1000) await download(`${src}/${key}.onnx`, onnx, `model suara ${base} (±60 MB)`);
  return onnx;
}

function runPiper(bin, model, text, out) {
  return new Promise((resolve, reject) => {
    const dir = path.dirname(bin);
    const args = ["--model", model, "--output_file", out, "--length_scale", env("PIPER_LENGTH_SCALE") || "1", "--sentence_silence", "0.25"];
    const espeak = path.join(dir, "espeak-ng-data");
    if (existsSync(espeak)) args.push("--espeak_data", espeak);
    const child = spawn(bin, args, { cwd: dir, stdio: ["pipe", "ignore", "pipe"] });
    let err = "";
    child.stderr.on("data", (d) => (err += d));
    child.on("error", (e) => reject(new Error(`Piper tidak bisa dijalankan: ${e.message}`)));
    child.on("exit", (code) => (code === 0 && existsSync(out) ? resolve() : reject(new Error(`Piper gagal (kode ${code}). ${err.split("\n").slice(-3).join(" ")}`))));
    child.stdin.end(text.replace(/\s+/g, " ") + "\n");
  });
}

// ---------- ElevenLabs / OpenAI ----------
/** Gabungkan waktu per huruf (ElevenLabs) jadi waktu per kata. */
function charsToWords(al) {
  const words = [];
  let cur = null;
  al.characters.forEach((ch, i) => {
    if (/\s/.test(ch)) {
      if (cur) words.push(cur);
      cur = null;
      return;
    }
    if (!cur) cur = { w: "", s: al.character_start_times_seconds[i], e: 0 };
    cur.w += ch;
    cur.e = al.character_end_times_seconds[i];
  });
  if (cur) words.push(cur);
  return words;
}

/** Cocokkan waktu kata hasil transkripsi dengan kata asli naskah (subtitle tetap memakai ejaan naskah). */
function alignWords(text, timed) {
  const words = text.split(/\s+/).filter(Boolean);
  if (!timed?.length) return undefined;
  if (timed.length === words.length) return words.map((w, i) => ({ w, s: timed[i].s, e: timed[i].e }));
  // Jumlah berbeda: sebar kata asli secara proporsional di antara awal & akhir bicara yang terdeteksi.
  const start = timed[0].s;
  const end = timed[timed.length - 1].e;
  const weight = (w) => w.length + 2;
  const total = words.reduce((a, w) => a + weight(w), 0);
  let t = start;
  return words.map((w) => {
    const d = ((end - start) * weight(w)) / total;
    const o = { w, s: t, e: t + d * 0.92 };
    t += d;
    return o;
  });
}

const round = (ws) => ws?.map((x) => ({ w: x.w, s: Math.round(x.s * 1000) / 1000, e: Math.round(x.e * 1000) / 1000 }));

async function cloudTts(text) {
  if (provider === "elevenlabs") {
    const base = env("ELEVENLABS_BASE_URL") || "https://api.elevenlabs.io";
    const voice = env("ELEVENLABS_VOICE_ID") || "21m00Tcm4TlvDq8ikWAM";
    const res = await fetch(`${base}/v1/text-to-speech/${voice}/with-timestamps?output_format=mp3_44100_128`, {
      method: "POST",
      headers: { "xi-api-key": env("ELEVENLABS_API_KEY"), "Content-Type": "application/json" },
      body: JSON.stringify({ text, model_id: env("ELEVENLABS_MODEL") || "eleven_multilingual_v2" }),
    });
    if (!res.ok) throw new Error(`ElevenLabs error ${res.status}${res.status === 401 ? " (API key salah)" : ""}`);
    const data = await res.json();
    const timed = data.alignment?.characters ? charsToWords(data.alignment) : undefined;
    return { audio: Buffer.from(data.audio_base64, "base64"), words: round(alignWords(text, timed)) };
  }
  const base = (env("OPENAI_BASE_URL") || "https://api.openai.com/v1").replace(/\/$/, "");
  const auth = { Authorization: `Bearer ${env("OPENAI_API_KEY")}` };
  const res = await fetch(`${base}/audio/speech`, {
    method: "POST",
    headers: { ...auth, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: env("OPENAI_TTS_MODEL") || "gpt-4o-mini-tts",
      voice: env("OPENAI_TTS_VOICE") || (gender === "male" ? "onyx" : "nova"),
      input: text,
      response_format: "mp3",
    }),
  });
  if (!res.ok) throw new Error(`OpenAI TTS error ${res.status}${res.status === 401 ? " (API key salah)" : ""}`);
  const audio = Buffer.from(await res.arrayBuffer());
  // Waktu kata: transkripsi ulang suara dengan timestamp per kata (Whisper). Kalau gagal, video memakai perkiraan.
  let words;
  try {
    const form = new FormData();
    form.append("file", new Blob([audio], { type: "audio/mpeg" }), "voice.mp3");
    form.append("model", env("OPENAI_STT_MODEL") || "whisper-1");
    form.append("response_format", "verbose_json");
    form.append("timestamp_granularities[]", "word");
    const tr = await fetch(`${base}/audio/transcriptions`, { method: "POST", headers: auth, body: form });
    if (tr.ok) {
      const j = await tr.json();
      words = round(alignWords(text, (j.words || []).map((x) => ({ w: x.word, s: x.start, e: x.end }))));
    }
  } catch {
    // abaikan: pakai perkiraan
  }
  return { audio, words };
}

// ---------- Jalankan ----------
mkdirSync(`${PUB}/voice`, { recursive: true });
const indexPath = `${PUB}/voice/index.json`;
const index = existsSync(indexPath) ? JSON.parse(readFileSync(indexPath, "utf8")) : {};
const names = { piper: "Piper (gratis, offline)", elevenlabs: "ElevenLabs", openai: "OpenAI TTS" };
console.log(`[suara] Membuat narasi dengan ${names[provider]}, suara ${gender === "male" ? "laki-laki" : "perempuan"}...`);

let piper = null;
let model = null;
if (provider === "piper") {
  try {
    piper = await ensurePiper();
    model = await ensureVoiceModel();
  } catch (e) {
    console.log(`[suara] Piper belum bisa dipakai: ${e.message}. Video dibuat tanpa suara (subtitle tetap ada).`);
    console.log("[suara] Cek koneksi internet lalu jalankan lagi. Atau isi API key ElevenLabs/OpenAI di .env.");
    for (const s of video.scenes) {
      delete s.voiceFile;
      delete s.words;
    }
    writeFileSync(videoPath, JSON.stringify(video, null, 2) + "\n");
    process.exit(0);
  }
}

for (const [i, scene] of video.scenes.entries()) {
  const text = (scene.narration || "").trim();
  const ext = provider === "piper" ? "wav" : "mp3";
  const file = `voice/scene-${i + 1}.${ext}`;
  const wordsFile = `${PUB}/voice/scene-${i + 1}.json`;
  if (!text) {
    delete scene.voiceFile;
    delete scene.words;
    continue;
  }
  const voiceId = provider === "piper" ? path.basename(model) : provider === "openai" ? env("OPENAI_TTS_VOICE") || gender : env("ELEVENLABS_VOICE_ID");
  const hash = createHash("sha1").update(`${provider}|${voiceId}|${env("PIPER_LENGTH_SCALE")}|${text}`).digest("hex");
  if (index[file] === hash && existsSync(`${PUB}/${file}`)) {
    scene.voiceFile = file;
    if (existsSync(wordsFile)) scene.words = JSON.parse(readFileSync(wordsFile, "utf8"));
    else delete scene.words;
    console.log(`[suara] Adegan ${i + 1}: sudah ada, dilewati.`);
    continue;
  }
  try {
    if (provider === "piper") {
      await runPiper(piper, model, text, path.resolve(PUB, file));
      // Piper tidak memberi waktu kata: video memperkirakannya dari panjang suara.
      delete scene.words;
      rmSync(wordsFile, { force: true });
    } else {
      const { audio, words } = await cloudTts(text);
      writeFileSync(`${PUB}/${file}`, audio);
      if (words?.length) {
        scene.words = words;
        writeFileSync(wordsFile, JSON.stringify(words));
      } else delete scene.words;
    }
    index[file] = hash;
    scene.voiceFile = file;
    console.log(`[suara] Adegan ${i + 1}: selesai.`);
  } catch (e) {
    delete scene.voiceFile;
    delete scene.words;
    console.log(`[suara] Adegan ${i + 1}: gagal (${e.message}). Adegan ini tanpa suara.`);
  }
