/** Aset "pita" selebar area: lapisan tanah & air. */
const BANDS = ["soil", "water"];
export const ASSET_IDS = [...Object.keys(ASSETS), ...BANDS];

const SIZE: Record<string, number> = { s: 75, m: 125, l: 200, xl: 320 };

/** Area elemen: "bottom" = tanah (di bawah subtitle, tempat karakter berpijak), lainnya relatif ke panggung langit. */
function areaBox(stage: Box, ground: Box, area: SceneElement["area"]): Box {
  const { left, top, width, height } = stage;
  switch (area) {
    case "top":
      return { left, top, width, height: height * 0.4 };
    case "bottom":
      return ground;
    case "middle":
      return { left, top: top + height * 0.3, width, height: height * 0.4 };
    case "left":
      return { left, top, width: width * 0.4, height };
    case "right":
      return { left: left + width * 0.6, top, width: width * 0.4, height };
    case "center":
      return { left: left + width * 0.3, top: top + height * 0.3, width: width * 0.4, height: height * 0.4 };
    default:
      return stage;
  }
}

/** Lapisan tanah (humus gelap → tanah → tanah liat → batu) yang bisa "terisi" naik. */
const SoilBand: React.FC<{ box: Box; level: number; t: number; u: number }> = ({ box, level, t, u }) => {
  const h = box.height * level;
  const layers = [
    { c: "#3f2a1d", f: 0.28 },
    { c: "#6b4423", f: 0.27 },
    { c: "#a0642c", f: 0.25 },
    { c: "#78716c", f: 0.2 },
  ];
  const wave = (k: number) => Math.sin(t * 1.2 + k) * 6 * u;
  let y = 0;
  return (
    <svg style={{ position: "absolute", left: box.left, top: box.top + box.height - h, overflow: "visible" }} width={box.width} height={Math.max(1, h)}>
      {layers.map((l, k) => {
        const top = y;
        y += l.f * h;
        const d = `M0 ${top + wave(k)} Q ${box.width * 0.25} ${top - 10 * u + wave(k + 1)} ${box.width * 0.5} ${top + wave(k + 2)} T ${box.width} ${top + wave(k + 3)} V ${h} H 0 Z`;
        return <path key={k} d={d} fill={l.c} />;
      })}
      {Array.from({ length: 26 }, (_, k) => (
        <circle key={k} cx={random(`s${k}`) * box.width} cy={h * (0.08 + random(`sy${k}`) * 0.9)} r={(3 + random(`sr${k}`) * 6) * u} fill="#000" opacity={0.18} />
      ))}
    </svg>
  );
};

const WaterBand: React.FC<{ box: Box; level: number; t: number; u: number }> = ({ box, level, t, u }) => {
  const h = box.height * level;
  const pts = Array.from({ length: 9 }, (_, k) => `${(box.width * k) / 8} ${Math.sin(t * 2 + k) * 8 * u}`).join(" L ");
  return (
    <svg style={{ position: "absolute", left: box.left, top: box.top + box.height - h, overflow: "visible" }} width={box.width} height={Math.max(1, h)}>
      <path d={`M ${pts} V ${h} H 0 Z`} fill="#0ea5e9" opacity={0.75} />
      <path d={`M ${pts}`} stroke="#bae6fd" strokeWidth={4 * u} fill="none" />
    </svg>
  );
};

/** Satu jenis elemen (bisa banyak salinan), digerakkan sesuai motion. */
const ElementGroup: React.FC<{ el: SceneElement; stage: Box; ground: Box; full: Box; seed: string; theme: Theme; localFrame: number }> = ({ el, stage, ground, full, seed, theme, localFrame }) => {
  const { fps, width, height } = useVideoConfig();
  const u = Math.min(width, height) / 1080;
  const box = el.area === "full" ? full : !el.area ? stage : areaBox(stage, ground, el.area);
  const t0 = localFrame / fps - (el.delay ?? 0);
  if (t0 < 0) return null;
  const motion = el.motion ?? "float";
  const asset = el.asset.trim();

  if (BANDS.includes(asset.toLowerCase())) {
    const target = el.size === "s" ? 0.35 : el.size === "l" ? 0.8 : el.size === "xl" ? 1 : 0.55;
    const level = motion === "fill" ? interpolate(t0, [0, 3.5], [0.02, target], { extrapolateRight: "clamp", easing: Easing.inOut(Easing.cubic) }) : target;
    const Band = asset.toLowerCase() === "soil" ? SoilBand : WaterBand;
    return <Band box={box} level={level} t={t0} u={u} />;
  }

  const lib = ASSETS[asset.toLowerCase()];
  const n = Math.max(1, Math.min(30, Math.round(el.count ?? 1)));
  const base = (SIZE[el.size ?? "m"] ?? 110) * u;
  return (
    <>
      {Array.from({ length: n }, (_, k) => {
        const r = (s: string) => random(`${seed}-${k}-${s}`);
        const size = base * (n > 1 ? 0.75 + r("sz") * 0.5 : 1);
        const stagger = n > 1 ? r("st") * Math.min(1.5, n * 0.12) : 0;
        const t = t0 - stagger;
        if (t < 0 && !["rain", "rise", "drift", "fly"].includes(motion)) return null;
        let x = box.left + (n > 1 ? (k + 0.2 + r("x") * 0.6) / n : 0.5) * box.width;
        let y = box.top + (n > 1 ? 0.15 + r("y") * 0.7 : 0.5) * box.height;
        let rot = 0;
        let scale = 1;
        let opacity = interpolate(t, [0, 0.4], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        let flip = 1;
        const ph = r("ph") * 6.28;
        switch (motion) {
          case "fall": {
            const dur = 2.6 + r("d") * 1.6;
            const p = Math.min(1, t / dur);
            const landY = box.top + box.height - size * (0.25 + r("ly") * 0.3);
            y = box.top - size + (landY - box.top + size) * Easing.out(Easing.quad)(p);
            x += Math.sin(t * 2.2 + ph) * 50 * u * (1 - p * 0.7);
            rot = p < 1 ? Math.sin(t * 2.6 + ph) * 40 : (r("rr") - 0.5) * 70;
            opacity = 1;
            break;
          }
          case "rain":
          case "rise": {
            const period = (asset === "drop" ? 0.9 : 2.2) + r("p") * 1.2;
            const p = (((t + 10) / period + r("o")) % 1 + 1) % 1;
            const span = box.height + size * 2;
            y = motion === "rain" ? box.top - size + p * span : box.top + box.height + size - p * span;
            x += Math.sin(t * 1.6 + ph) * (motion === "rise" ? 25 : 8) * u;
            opacity = interpolate(p, [0, 0.1, 0.85, 1], [0, 1, 1, 0]);
            rot = motion === "rain" ? 0 : Math.sin(t + ph) * 15;
            if (motion === "rise") scale = 0.7 + p * 0.5;
            break;
          }
          case "dash": {
            // melesat cepat dari kiri ke kanan berulang, dengan jejak (cahaya, roket, komet)
            const period = 0.9 + r("p") * 0.7;
            const p = (((t + 10) / period + r("o")) % 1 + 1) % 1;
            x = box.left - size + p * (box.width + size * 2);
            y += Math.sin(ph) * 10 * u;
            opacity = interpolate(p, [0, 0.08, 0.9, 1], [0, 1, 1, 0]);
            scale = 1;
            flip = 1;
            break;
          }
          case "drift":
          case "fly": {
            const speed = 0.08 + r("sp") * 0.06;
            const p = (((t + 10) * speed + r("o")) % 1.2) - 0.1;
            x = box.left + p * box.width;
            y += motion === "fly" ? -Math.sin(p * Math.PI * 2 + ph) * box.height * 0.15 : Math.sin(t * 0.9 + ph) * 12 * u;
            rot = motion === "fly" ? Math.sin(t * 8) * 8 : 0;
            opacity = interpolate(p, [-0.1, 0, 1, 1.1], [0, 1, 1, 0]);
            break;
          }
          case "crawl": {
            const sp = 0.35 + r("sp") * 0.25;
            x += Math.sin(t * sp + ph) * box.width * 0.18;
            y = box.top + box.height - size * (0.3 + r("cy") * 0.4);
            flip = Math.cos(t * sp + ph) >= 0 ? 1 : -1;
            break;
          }
          case "swim": {
            x += Math.sin(t * 0.7 + ph) * box.width * 0.25;
            y += Math.sin(t * 1.5 + ph) * 25 * u;
            flip = Math.cos(t * 0.7 + ph) >= 0 ? 1 : -1;
            rot = Math.sin(t * 1.5 + ph) * 10;
            break;
          }
          case "orbit": {
            const a = t * 0.8 + (k / n) * Math.PI * 2;
            const rad = Math.min(box.width, box.height) * 0.35;
            x = box.left + box.width / 2 + Math.cos(a) * rad;
            y = box.top + box.height / 2 + Math.sin(a) * rad;
            break;
          }
          case "grow":
            scale = Easing.out(Easing.back(1.6))(Math.min(1, t / 1.3));
            rot = Math.sin(t * 1.4 + ph) * 3;
            break;
          case "pop":
            scale = spring({ frame: Math.round(t * fps), fps, config: { damping: 9, stiffness: 140 } });
            y += Math.sin(t * 1.8 + ph) * 8 * u;
            break;
          case "spin":
            rot = t * 120 * (r("sd") > 0.5 ? 1 : -1);
            break;
          case "pulse":
            scale = 1 + Math.sin(t * 4 + ph) * 0.12;
            break;
          case "wiggle":
            rot = Math.sin(t * 9 + ph) * 12;
            scale = 1 + Math.sin(t * 7 + ph) * 0.05;
            break;
          case "bounce":
            y -= Math.abs(Math.sin(t * 3 + ph)) * 50 * u;
            break;
          case "shrink": {
            // membusuk/terurai: mengecil, memudar, bergetar
            const p = interpolate(t, [0.6, 3.6], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.quad) });
            scale = 1 - p * 0.85;
            opacity = Math.min(opacity, 1 - p * 0.75);
            rot = Math.sin(t * 14 + ph) * 6 * p + (r("rr") - 0.5) * 60;
            y += p * 20 * u;
            break;
          }
          case "float":
          default:
            y += Math.sin(t * 1.5 + ph) * 16 * u;
            x += Math.cos(t * 1.1 + ph) * 10 * u;
            rot = Math.sin(t * 1.2 + ph) * 6;
        }
        const style: React.CSSProperties = {
          position: "absolute",
          left: x - size / 2,
          top: y - size / 2,
          width: size,
          height: size,
          opacity,
          transform: `rotate(${rot}deg) scale(${scale * flip}, ${scale})`,
          transformOrigin: motion === "grow" ? "50% 100%" : "50% 50%",
        };
        return lib ? (
          <svg key={k} viewBox="-50 -50 100 100" style={{ ...style, overflow: "visible" }}>
            {lib.draw({ phase: t + ph, color: el.color, theme })}
          </svg>
        ) : (
          <div key={k} style={{ ...style, fontSize: size * 0.82, lineHeight: `${size}px`, textAlign: "center" }}>
            {asset}
          </div>
        );
      })}
      {el.label ? (
        <div
          style={{
            position: "absolute",
            left: box.left,
            width: box.width,
            top: box.top + box.height + 6 * u,
            textAlign: "center",
            fontFamily: theme.font,
            fontWeight: 800,
            fontSize: 34 * u,
            color: theme.text,
            opacity: interpolate(t0, [0.3, 0.8], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
            textShadow: "0 2px 8px rgba(0,0,0,0.5)",
          }}
        >
          {el.label}
        </div>
      ) : null}
    </>
  );
};

/** Semua elemen satu adegan. localFrame = frame sejak adegan mulai. */
export const Elements: React.FC<{ elements: SceneElement[]; stage: Box; ground: Box; full: Box; sceneIndex: number; theme: Theme }> = ({ elements, stage, ground, full, sceneIndex, theme }) => {
  const frame = useCurrentFrame();
  return (
    <>
      {elements.slice(0, 12).map((el, k) => (
        <ElementGroup key={k} el={el} stage={stage} ground={ground} full={full} seed={`e${sceneIndex}-${k}`} theme={theme} localFrame={frame} />
      ))}
    </>
  );
};

