// Latar ruangan kartun (gaya garis tebal + warna datar) untuk video cerita. Digambar di kanvas 1920x1920 dengan
// "slice": video tegak (9:16) memakai bagian tengah selebar 1080, video mendatar (16:9) bagian tengah setinggi 1080.
// Jadi benda penting diletakkan di kotak tengah (x 420-1500, y 420-1500); lantai mulai y 1180 supaya kaki tokoh berpijak.
// Semua statis kecuali sedikit gerak (awan, lampu, bintang) dari frame, TANPA filter/blur (render tetap ringan).
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import type { Theme } from "./theme";
import type { Backdrop as BackdropId } from "./types";

export const BACKDROPS: BackdropId[] = ["kamar", "dapur", "lab", "bengkel", "kantor", "kelas", "taman", "jalan", "angkasa"];

const INK = "#2b2118";
const W = 1920;
const FLOOR = 1180;
const line = { stroke: INK, strokeWidth: 7, strokeLinejoin: "round" as const, strokeLinecap: "round" as const };

const Room: React.FC<{ wall: string; floor: string; floor2: string; children?: React.ReactNode }> = ({ wall, floor, floor2, children }) => (
  <>
    <rect x={0} y={0} width={W} height={FLOOR} fill={wall} />
    <rect x={0} y={FLOOR} width={W} height={W - FLOOR} fill={floor} />
    {Array.from({ length: 9 }, (_, i) => (
      <line key={i} x1={i * 240} y1={FLOOR} x2={i * 240 - 160} y2={W} stroke={floor2} strokeWidth={6} />
    ))}
    <rect x={0} y={FLOOR - 26} width={W} height={26} fill={floor2} {...line} />
    {children}
  </>
);

const Window: React.FC<{ x: number; y: number; w: number; h: number; sky: string; curtain?: string }> = ({ x, y, w, h, sky, curtain }) => (
  <g>
    <rect x={x} y={y} width={w} height={h} fill={sky} {...line} />
    <line x1={x + w / 2} y1={y} x2={x + w / 2} y2={y + h} {...line} />
    <line x1={x} y1={y + h / 2} x2={x + w} y2={y + h / 2} {...line} />
    {curtain && (
      <>
        <path d={`M${x - 40} ${y - 30} h${w / 3 + 40} q-30 ${h / 2} 0 ${h + 60} h${-w / 3 - 40} z`} fill={curtain} {...line} />
        <path d={`M${x + w + 40} ${y - 30} h${-w / 3 - 40} q30 ${h / 2} 0 ${h + 60} h${w / 3 + 40} z`} fill={curtain} {...line} />
      </>
    )}
  </g>
);

const Shelf: React.FC<{ x: number; y: number; w: number; items: string[] }> = ({ x, y, w, items }) => (
  <g>
    <rect x={x} y={y} width={w} height={22} fill="#b07a4f" {...line} />
    {items.map((c, i) => {
      const bx = x + 30 + i * ((w - 60) / Math.max(1, items.length));
      return i % 2 ? (
        <path key={i} d={`M${bx} ${y} v-70 q0 -20 20 -20 h20 q20 0 20 20 v70 z`} fill={c} {...line} />
      ) : (
        <rect key={i} x={bx} y={y - 110} width={50} height={110} rx={8} fill={c} {...line} />
      );
    })}
  </g>
);

const Plant: React.FC<{ x: number; y: number; s?: number }> = ({ x, y, s = 1 }) => (
  <g transform={`translate(${x} ${y}) scale(${s})`}>
    <ellipse cx={-40} cy={-150} rx={40} ry={80} fill="#4caf50" {...line} transform="rotate(-25 -40 -150)" />
    <ellipse cx={40} cy={-160} rx={40} ry={85} fill="#66bb6a" {...line} transform="rotate(25 40 -160)" />
    <ellipse cx={0} cy={-190} rx={36} ry={90} fill="#43a047" {...line} />
    <path d="M-70 -70 h140 l-20 100 h-100 z" fill="#e07a5f" {...line} />
  </g>
);

const Clock: React.FC<{ x: number; y: number; t: number }> = ({ x, y, t }) => (
  <g>
    <circle cx={x} cy={y} r={70} fill="#fffaf0" {...line} />
    <line x1={x} y1={y} x2={x} y2={y - 45} {...line} />
    <line x1={x} y1={y} x2={x + 40 * Math.sin(t * 0.6)} y2={y - 40 * Math.cos(t * 0.6)} {...line} />
  </g>
);

function Scenery({ id, t }: { id: BackdropId; t: number }) {
  switch (id) {
    case "kamar":
      return (
        <Room wall="#bfe3f2" floor="#d9a86c" floor2="#c08f55">
          <Window x={760} y={380} w={400} h={360} sky="#fff3c4" curtain="#f7a8b8" />
          <rect x={300} y={560} width={300} height={220} fill="#ffd166" {...line} transform="rotate(-3 450 670)" />
          <circle cx={450} cy={650} r={55} fill="#ef476f" {...line} />
          <rect x={1300} y={980} width={420} height={200} rx={20} fill="#7bdff2" {...line} />
          <rect x={1300} y={900} width={140} height={100} rx={30} fill="#ffffff" {...line} />
          <rect x={1280} y={1170} width={460} height={30} fill="#5b8def" {...line} />
          <ellipse cx={960} cy={1500} rx={420} ry={90} fill="#f4978e" {...line} />
