  return (
    <AbsoluteFill style={{ top: "-8%", left: "-8%", right: "-8%", bottom: "-8%", width: "auto", height: "auto" }}>
      <svg viewBox={`0 0 ${W} ${W}`} width="100%" height="100%" preserveAspectRatio="xMidYMid slice">
