import { AbsoluteFill, interpolate, random, useCurrentFrame, useVideoConfig } from "remotion";
import type { Theme } from "./theme";

/** Latar bergerak pelan: gradien + tiga cahaya yang melayang. */
export const Background: React.FC<{ theme: Theme }> = ({ theme }) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const t = frame / useVideoConfig().fps;
  const size = Math.max(width, height) * 0.7;
  const blob = (i: number, color: string) => {
    const x = width * (0.2 + 0.6 * ((Math.sin(t * 0.35 + i * 2.1) + 1) / 2));
    const y = height * (0.15 + 0.7 * ((Math.cos(t * 0.27 + i * 1.7) + 1) / 2));
    return (
      <div
        key={i}
        style={{
          position: "absolute",
          left: x - size / 2,
          top: y - size / 2,
          width: size,
          height: size,
          borderRadius: "50%",
          // Tanpa filter blur: gradien radial sudah lembut, dan blur membuat render 2x lebih berat (CPU).
          background: `radial-gradient(circle, ${color}55 0%, ${color}00 65%)`,
        }}
      />
    );
  };
  const grid = interpolate(frame, [0, 600], [0, 120]);
  return (
    <AbsoluteFill style={{ background: `linear-gradient(160deg, ${theme.bg[0]}, ${theme.bg[1]})`, overflow: "hidden" }}>
      {theme.blobs.map((c, i) => blob(i, c))}
      <AbsoluteFill
        style={{
          backgroundImage: `linear-gradient(${theme.text}0d 1px, transparent 1px), linear-gradient(90deg, ${theme.text}0d 1px, transparent 1px)`,
          backgroundSize: "60px 60px",
          backgroundPosition: `0 ${grid}px`,
        }}
      />
      {/* partikel cahaya yang melayang naik pelan */}
      {Array.from({ length: 22 }, (_, k) => {
        const sp = 0.015 + random(`bp${k}`) * 0.025;
        const p = (random(`bo${k}`) + t * sp) % 1;
        const r = (3 + random(`br${k}`) * 6) * (Math.min(width, height) / 1080);
        return (
          <div
            key={`p${k}`}
            style={{
              position: "absolute",
              left: width * random(`bx${k}`) + Math.sin(t * 0.8 + k) * 30,
              top: height * (1.05 - p * 1.1),
              width: r * 2,
              height: r * 2,
              borderRadius: "50%",
              background: theme.blobs[k % 3],
              opacity: 0.5 * Math.sin(p * Math.PI),
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

