// Gerak kamera per adegan: zoom, geser, getar, miring, sapuan, dll.
// Kamera menggerakkan "dunia" (adegan + karakter), latar ikut pelan (parallax), subtitle tidak ikut.
// Pergantian kamera antar adegan di-blend supaya tidak melompat.
import { AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";
import { layoutFor } from "./layout";
import { positionFor, sceneAt, sceneStarts, transitionFrames } from "./timing";
import type { CameraMove, Scene } from "./types";
import type { VideoProps } from "./Video";

type Cam = { s: number; x: number; y: number; r: number; blur: number; ox: number; oy: number };
// Titik pusat sedikit di atas tengah supaya judul di atas tetap terlihat saat zoom.
const REST: Cam = { s: 1.03, x: 0, y: 0, r: 0, blur: 0, ox: 0.5, oy: 0.42 };

const ease = Easing.inOut(Easing.cubic);
const S = Math.sin;

/** Getar acak tapi tetap (deterministik) dari gabungan gelombang. */
const noise = (t: number, k: number) => S(t * 37.1 + k) * 0.5 + S(t * 23.7 + k * 2.3) * 0.3 + S(t * 61.3 + k * 4.1) * 0.2;

/** Kamera otomatis yang bervariasi sesuai jenis adegan. */
export function autoCamera(scene: Scene, i: number): CameraMove {
  if (scene.action === "surprised") return "shake";
  switch (scene.type) {
    case "title":
      return "zoom-in";
    case "stat":
      return "punch-in";
    case "quote":
      return "dutch";
    case "bullets":
      return "handheld";
    case "cta":
      return "zoom-in";
    case "scene":
      return (["pan-right", "zoom-out", "pan-left", "orbit", "pan-down", "focus-character"] as const)[i % 6];
    default:
      return i % 2 ? "handheld" : "zoom-in";
  }
}

/** Posisi kamera untuk satu gerakan pada detik t dari total dur detik. Satuan x/y: fraksi lebar/tinggi layar. */
export function cameraAt(move: CameraMove, t: number, dur: number, focus: { x: number; y: number }): Cam {
  const p = Math.min(1, Math.max(0, t / Math.max(0.1, dur)));
  const e = ease(p);
  const breath = { x: S(t * 0.7) * 0.003, y: S(t * 0.9) * 0.003 };
  const c: Cam = { ...REST, x: breath.x, y: breath.y };
  switch (move) {
    case "static":
      return c;
    case "zoom-in":
      return { ...c, s: 1.02 + 0.12 * e };
    case "zoom-out":
      return { ...c, s: 1.15 - 0.12 * e };
    case "punch-in": {
      // hentakan cepat lalu tahan, sedikit memantul
      const k = interpolate(t, [0, 0.35, 0.6], [0, 1.08, 1], { extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) });
      return { ...c, s: 1.03 + 0.13 * k };
    }
    case "pan-left":
      return { ...c, s: 1.08, x: 0.035 - 0.07 * e };
    case "pan-right":
      return { ...c, s: 1.08, x: -0.035 + 0.07 * e };
    case "pan-up":
      return { ...c, s: 1.08, y: 0.025 - 0.05 * e };
    case "pan-down":
      return { ...c, s: 1.08, y: -0.025 + 0.05 * e };
    case "shake": {
      // getar kuat di awal lalu mereda, tetap sedikit bergetar
      const amp = 0.012 * Math.max(0.15, 1 - t / 1.2);
      return { ...c, s: 1.08, x: noise(t, 1) * amp, y: noise(t, 7) * amp, r: noise(t, 3) * amp * 60 };
    }
    case "handheld":
      return { ...c, s: 1.07, x: S(t * 1.3) * 0.006 + S(t * 2.9) * 0.002, y: S(t * 1.1 + 1) * 0.005 + S(t * 3.3) * 0.002, r: S(t * 0.8) * 0.6 };
    case "dutch":
      return { ...c, s: 1.08, r: -3 + 5 * e };
    case "whip": {
      // sapuan cepat masuk dari samping dengan blur gerak
      const k = interpolate(t, [0, 0.45], [1, 0], { extrapolateRight: "clamp", easing: Easing.out(Easing.exp) });
      return { ...c, s: 1.08 + 0.04 * e, x: 0.35 * k, blur: 14 * k };
    }
    case "orbit":
      return { ...c, s: 1.07 + 0.04 * e, x: S(p * Math.PI * 2) * 0.03, y: (1 - Math.cos(p * Math.PI * 2)) * 0.015, r: S(p * Math.PI * 2) * 2 };
    case "focus-character":
      return { ...c, s: 1.03 + 0.18 * e, ox: focus.x, oy: focus.y };
    case "bounce": {
      const b = Math.abs(S(t * Math.PI * 1.6));
      return { ...c, s: 1.06 + 0.035 * b, y: -0.006 * b };
    }
    default:
      return { ...c, s: 1.02 + 0.06 * e };
  }
}

const lerp = (a: Cam, b: Cam, k: number): Cam => ({
  s: a.s + (b.s - a.s) * k,
  x: a.x + (b.x - a.x) * k,
  y: a.y + (b.y - a.y) * k,
  r: a.r + (b.r - a.r) * k,
  blur: a.blur + (b.blur - a.blur) * k,
  ox: a.ox + (b.ox - a.ox) * k,
  oy: a.oy + (b.oy - a.oy) * k,
});

/** Kamera di frame sekarang: kamera adegan aktif, di-blend dari kamera adegan sebelumnya saat transisi. */
function useCamera(video: VideoProps): Cam {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const starts = sceneStarts(video.sceneFrames, fps);
  if (!video.scenes.length) return REST;
  const camOf = (k: number, f: number) => {
    const sc = video.scenes[k];
    const L = layoutFor(width, height, video.character?.show !== false, positionFor(sc, k, video));
    const move = sc.camera && sc.camera !== "auto" ? sc.camera : autoCamera(sc, k);
    return cameraAt(move, (f - starts[k]) / fps, video.sceneFrames[k] / fps, { x: L.char.x / width, y: (L.char.feet - L.char.h * 0.6) / height });
  };
  const i = sceneAt(frame, starts);
  const cur = camOf(i, frame);
  const local = frame - starts[i];
  const blendF = transitionFrames(fps) + Math.round(fps * 0.2);
  if (i > 0 && local < blendF) {
    const prev = camOf(i - 1, frame);
    return lerp(prev, cur, ease(local / blendF));
  }
  return cur;
}

/** Bungkus "dunia" dengan kamera. depth < 1 = parallax (latar bergerak lebih sedikit). */
export const CameraRig: React.FC<{ video: VideoProps; depth?: number; bleed?: boolean; children: React.ReactNode }> = ({ video, depth = 1, bleed, children }) => {
  const { width, height } = useVideoConfig();
  const c = useCamera(video);
  const s = 1 + (c.s - 1) * depth;
  return (
    <AbsoluteFill
      style={{
        // latar diberi ruang lebih supaya tepinya tidak terlihat saat kamera bergeser/miring
        ...(bleed ? { inset: "-12%", width: "auto", height: "auto" } : {}),
        transform: `translate(${c.x * width * depth}px, ${c.y * height * depth}px) rotate(${c.r * depth}deg) scale(${s})`,
        transformOrigin: `${c.ox * 100}% ${c.oy * 100}%`,
        filter: c.blur > 0.3 ? `blur(${c.blur * depth}px)` : undefined,
      }}
    >
      {children}
    </AbsoluteFill>
  );
};

