import { layoutFor } from "./layout";
import type { Theme } from "./theme";
import { positionFor, sceneAt, sceneStarts, speakSecondsFor, wordTimings } from "./timing";
import type { Word } from "./types";
import type { VideoProps } from "./Video";

/** Pecah kata jadi baris pendek (berhenti juga di tanda baca) supaya enak dibaca. */
function chunks(words: Word[], max: number) {
  const out: Word[][] = [];
  let cur: Word[] = [];
  for (const w of words) {
    cur.push(w);
    if (cur.length >= max || /[.,!?;:]$/.test(w.w)) {
      out.push(cur);
      cur = [];
    }
  }
  if (cur.length) out.push(cur);
  return out;
}

/**
 * Subtitle karaoke: kata yang SEDANG diucapkan disorot (kotak warna yang ikut berpindah),
 * kata yang sudah diucapkan terang, yang belum agak redup. Waktu kata dari suara AI (scene.words)
 * atau perkiraan kalau tanpa suara.
 */
export const Captions: React.FC<{ video: VideoProps; theme: Theme }> = ({ video, theme }) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const starts = sceneStarts(video.sceneFrames, fps);
  if (!video.scenes.length) return null;
  const i = sceneAt(frame, starts);
  const scene = video.scenes[i];
  const t = (frame - starts[i]) / fps;
  const speak = speakSecondsFor(video.voiceSeconds?.[i] ?? 0, video.sceneFrames[i] / fps);
  const words = wordTimings(scene, speak);
  if (!words.length) return null;
  const portrait = height > width * 1.2;
  if (video.captionStyle === "kata") return <WordPop video={video} theme={theme} words={words} t={t} sceneStart={starts[i]} index={i} />;
  const lines = chunks(words, portrait ? 4 : 6);
  // Baris aktif: yang memuat kata sekarang, atau baris terakhir yang sudah lewat.
  let li = 0;
  for (let k = 0; k < lines.length; k++) if (t >= lines[k][0].s - 0.05) li = k;
  const line = lines[li];
  const lineStart = line[0].s;
  const lineEnd = line[line.length - 1].e;
  const isLast = li === lines.length - 1;
  const fadeIn = interpolate(t, [lineStart - 0.15, lineStart], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const fadeOut = isLast ? interpolate(t, [lineEnd + 0.5, lineEnd + 0.8], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) : 1;
  const visible = Math.min(fadeIn, fadeOut);
  if (visible <= 0) return null;
  const enter = spring({ frame: frame - starts[i] - Math.round(lineStart * fps), fps, config: { damping: 16, stiffness: 160 } });
  const L = layoutFor(width, height, video.character?.show !== false, positionFor(scene, i, video));
  const box = captionBox(video, width, height, L.captions);
  const u = Math.min(width, height) / 1080;
  const size = (portrait ? 64 : 54) * u;
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <div
        style={{
          position: "absolute",
          left: box.left,
          top: box.top,
          width: box.width,
          height: box.height,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: visible,
          transform: `translateY(${(1 - enter) * 24 * u}px) scale(${0.94 + 0.06 * enter})`,
        }}
      >
        <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: `${10 * u}px ${12 * u}px`, padding: `${14 * u}px ${18 * u}px`, borderRadius: 26 * u, background: "rgba(10,8,25,0.42)", fontFamily: theme.font, fontWeight: 900, fontSize: size, lineHeight: 1.15 }}>
          {line.map((w, k) => {
            const active = t >= w.s && t < w.e;
            const done = t >= w.e;
            const pop = spring({ frame: frame - starts[i] - Math.round(w.s * fps), fps, config: { damping: 12, stiffness: 220 } });
            return (
              <span
                key={k}
                style={{
                  position: "relative",
                  padding: `${2 * u}px ${12 * u}px`,
                  borderRadius: 14 * u,
                  color: "#ffffff",
                  opacity: done || active ? 1 : 0.55,
                  background: active ? `linear-gradient(90deg, ${theme.accent}, ${theme.accent2})` : "transparent",
                  transform: `scale(${active ? 1 + 0.12 * pop : 1}) translateY(${active ? -4 * u * pop : 0}px)`,
                  WebkitTextStroke: active ? undefined : `${2.5 * u}px rgba(15,10,30,0.85)`,
                  paintOrder: "stroke fill",
                  textShadow: active ? "none" : `0 ${3 * u}px ${10 * u}px rgba(0,0,0,0.75), 0 0 ${2 * u}px rgba(0,0,0,0.9)`,
                  boxShadow: active ? `0 ${6 * u}px ${24 * u}px ${theme.accent}88` : "none",
                }}
              >
                {w.w}
              </span>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

/** Gaya "kata": satu kata besar di tengah yang meletup saat diucapkan (gaya video cerita/explainer). */
const WordPop: React.FC<{ video: VideoProps; theme: Theme; words: Word[]; t: number; sceneStart: number; index: number }> = ({ video, theme, words, t, sceneStart, index }) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  let k = -1;
  for (let j = 0; j < words.length; j++) if (t >= words[j].s - 0.02) k = j;
  if (k < 0) return null;
  const w = words[k];
  if (k === words.length - 1 && t > w.e + 0.6) return null;
  const pop = spring({ frame: frame - sceneStart - Math.round(w.s * fps), fps, config: { damping: 10, stiffness: 260 } });
  const L = layoutFor(width, height, video.character?.show !== false, positionFor(video.scenes[index], index, video));
  const box = captionBox(video, width, height, L.captions);
  const u = Math.min(width, height) / 1080;
  const portrait = height > width * 1.2;
  const text = w.w.replace(/[.,!?;:]+$/, "");
  const size = Math.min((portrait ? 118 : 96) * u, (box.width / Math.max(4, text.length)) * 1.7);
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <div style={{ position: "absolute", left: box.left, top: box.top, width: box.width, height: box.height, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <span
          style={{
            fontFamily: theme.font,
            fontWeight: 900,
            fontSize: size,
            color: "#ffffff",
            WebkitTextStroke: `${7 * u}px #1a1410`,
            paintOrder: "stroke fill",
            textShadow: `0 ${6 * u}px 0 #1a1410`,
            transform: `scale(${0.6 + 0.4 * pop}) rotate(${(k % 2 ? 2 : -2) * (1 - pop)}deg)`,
            letterSpacing: 1 * u,
          }}
        >
          {text}
        </span>
      </div>
    </AbsoluteFill>
  );
};

/** Mode cerita di layar mendatar/kotak: tokoh berjajar di bawah, jadi subtitle dipindah ke atas tengah. */
function captionBox(video: VideoProps, width: number, height: number, normal: { left: number; top: number; width: number; height: number }) {
  const portrait = height > width * 1.2;
  if ((video.cast?.length ?? 0) < 2 || portrait) return normal;
  return { left: width * 0.1, top: height * 0.05, width: width * 0.8, height: height * 0.2 };
}

