// Karakter maskot vektor (SVG) yang digerakkan per frame: napas, kedip, gerak tangan/kaki,
// lompat, dan mulut yang bergerak mengikuti kata yang sedang diucapkan (lip-sync).
// Semua gerakan dihitung dari waktu (detik), tidak memakai animasi CSS, supaya render konsisten.
import type { Theme } from "./theme";
import type { CharacterAction, CharacterLook, Hair, Mood } from "./types";

/** Sudut dalam derajat. U = lengan atas (positif = mengangkat keluar), F = lengan bawah (relatif ke lengan atas). */
export type Pose = {
  lU: number;
  lF: number;
  rU: number;
  rF: number;
  /** Miring badan (derajat) */
  tilt: number;
  /** Arah pandang -1..1 */
  lookX: number;
  lookY: number;
  /** Alis naik (0..1) */
  brow: number;
  /** Tinggi lompat (0..1) */
  jump: number;
  /** Ayunan kaki (derajat) */
  leg: number;
  /** Mulut terbuka karena ekspresi (0..1), mis. kaget */
  gasp: number;
};

const S = Math.sin;
const TAU = Math.PI * 2;

/** Pose untuk konten di sebelah KANAN karakter (dir=1). Arah lain dicerminkan di mirrorPose(). */
function basePose(action: CharacterAction, t: number, dirUp: boolean, talking: boolean): Pose {
  const breathe = S(t * 2.2);
  const p: Pose = { lU: 12 + breathe * 2, lF: 14, rU: 12 - breathe * 2, rF: 14, tilt: S(t * 1.1) * 1.5, lookX: 0.35, lookY: 0, brow: 0, jump: 0, leg: 0, gasp: 0 };
  // Sedikit gerak tangan setiap bicara, supaya tidak kaku.
  const gest = talking ? 1 : 0;
  switch (action) {
    case "wave": {
      const k = Math.min(1, t / 0.4);
      p.rU = 12 + (150 - 12) * k;
      p.rF = 20 + S(t * 11) * 28 * k;
      p.tilt = -3 + S(t * 3) * 2;
      p.lookX = 0;
      p.brow = 0.3;
      break;
    }
    case "point":
      p.rU = dirUp ? 158 : 92 + S(t * 3) * 3;
      p.rF = dirUp ? 4 : -6;
      p.lU = 14 + gest * S(t * 5) * 6;
      p.tilt = dirUp ? -2 : 4;
      p.lookX = dirUp ? 0.2 : 0.8;
      p.lookY = dirUp ? -0.8 : 0;
      break;
    case "present":
      p.lU = 50 + S(t * 4) * 6 * gest;
      p.lF = 30;
      p.rU = (dirUp ? 120 : 70) + S(t * 4 + 1) * 8 * gest;
      p.rF = dirUp ? 20 : 35;
      p.lookX = dirUp ? 0 : 0.7;
      p.lookY = dirUp ? -0.6 : 0;
      p.brow = 0.2;
      break;
    case "think":
      p.rU = 22;
      p.rF = -165 + S(t * 2) * 4;
      p.lU = 18;
      p.lF = 70;
      p.tilt = 6 + S(t * 1.3) * 1.5;
      p.lookX = -0.4;
      p.lookY = -0.85;
      p.brow = 0.5;
      break;
    case "surprised": {
      const k = Math.min(1, t / 0.25);
      p.lU = 12 + 60 * k;
      p.lF = 14 + 70 * k;
      p.rU = 12 + 60 * k;
      p.rF = 14 + 70 * k;
      p.jump = Math.max(0, S(Math.min(1, t / 0.45) * Math.PI)) * 0.35;
      p.brow = 1;
      p.gasp = 0.75;
      p.lookX = 0;
      break;
    }
    case "celebrate": {
      const k = Math.min(1, t / 0.35);
      p.lU = 12 + 143 * k;
      p.rU = 12 + 143 * k;
      p.lF = 10 + S(t * 9) * 18;
      p.rF = 10 - S(t * 9) * 18;
      p.jump = Math.abs(S(t * Math.PI * 1.6)) * 0.45 * k;
      p.brow = 0.6;
      p.lookX = 0;
      break;
    }
    case "talk":
      p.rU = 30 + S(t * 4.5) * 16;
      p.rF = 45 + S(t * 4.5 + 1.2) * 22;
      p.lU = 14 + S(t * 3.2 + 2) * 6;
      p.lF = 20 + S(t * 3.2) * 10;
      p.tilt = S(t * 2.4) * 3;
      p.brow = Math.max(0, S(t * 3.1)) * 0.4;
      break;
    case "idle":
    default:
      break;
  }
  return p;
}

function mirrorPose(p: Pose): Pose {
  return { ...p, lU: p.rU, lF: p.rF, rU: p.lU, rF: p.lF, tilt: -p.tilt, lookX: -p.lookX };
}

export function poseFor(action: CharacterAction, t: number, dir: 1 | -1 | 0, talking: boolean): Pose {
  const p = basePose(action, t, dir === 0, talking);
  return dir === -1 ? mirrorPose(p) : p;
}

export function lerpPose(a: Pose, b: Pose, k: number): Pose {
  const out = { ...b };
  for (const key of Object.keys(b) as (keyof Pose)[]) out[key] = a[key] + (b[key] - a[key]) * k;
  return out;
}

/** Gerak jalan: kaki & tangan berayun, badan naik-turun. phase dalam radian. */
export function walkPose(p: Pose, phase: number, amount: number, towards: number): Pose {
  if (amount <= 0) return p;
  const swing = S(phase);
  return {
    ...p,
    leg: swing * 22 * amount,
    lU: p.lU + swing * 22 * amount,
    rU: p.rU - swing * 22 * amount,
    tilt: p.tilt + towards * 5 * amount,
    lookX: p.lookX * (1 - amount) + towards * amount,
  };
}

/** Seberapa terbuka mulut (0..1) saat mengucapkan kata: mengikuti jumlah suku kata. */
export function mouthOpen(word: string, progress: number) {
  const syl = Math.max(1, (word.toLowerCase().match(/[aiueoy]+/g) || []).length);
  return Math.abs(S(progress * Math.PI * syl)) * 0.85 + 0.15;
}

const Arm: React.FC<{ x: number; y: number; u: number; f: number; side: 1 | -1; color: string; hand: string }> = ({ x, y, u, f, side, color, hand }) => (
  <g transform={`rotate(${u * side} ${x} ${y})`}>
    <line x1={x} y1={y} x2={x} y2={y + 72} stroke={color} strokeWidth={26} strokeLinecap="round" />
    <g transform={`rotate(${f * side} ${x} ${y + 72})`}>
      <line x1={x} y1={y + 72} x2={x} y2={y + 132} stroke={color} strokeWidth={24} strokeLinecap="round" />
      <circle cx={x} cy={y + 142} r={22} fill={hand} />
    </g>
  </g>
);

const Eye: React.FC<{ cx: number; cy: number; open: number; lookX: number; lookY: number; robot: boolean; glow: string }> = ({ cx, cy, open, lookX, lookY, robot, glow }) =>
  robot ? (
    <rect x={cx - 20} y={cy - 22 * open} width={40} height={Math.max(4, 44 * open)} rx={14} fill={glow} style={{ filter: `drop-shadow(0 0 8px ${glow})` }} />
  ) : (
    <g>
      <ellipse cx={cx} cy={cy} rx={25} ry={Math.max(2, 30 * open)} fill="#ffffff" />
      {open > 0.25 && (
        <>
          <circle cx={cx + lookX * 9} cy={cy + lookY * 10 + 2} r={13} fill="#111827" />
          <circle cx={cx + lookX * 9 + 5} cy={cy + lookY * 10 - 4} r={4.5} fill="#ffffff" />
        </>
      )}
    </g>
  );

/**
 * Gambar karakter. Koordinat internal: kotak 400x620, kaki di bawah.
 * mouth = bukaan mulut 0..1, blink = 0 (tertutup)..1 (terbuka).
 */
export const Character: React.FC<{
  pose: Pose;
  mouth: number;
  blink: number;
  breathe: number;
  look: CharacterLook;
  theme: Theme;
  height: number;
  /** emoji yang dipegang/di atas kepala (opsional) */
  prop?: string;
  antenna: number;
  /** Ekspresi kartun (mode cerita) */
  mood?: Mood;
  /** Waktu (detik) untuk animasi kecil ekspresi: air mata, keringat, simbol */
  time?: number;
  /** Warna badan sendiri (mode cerita, beda tiap tokoh) */
  tint?: string;
  hair?: Hair;
  hairColor?: string;
  /** Pembeda id gradien kalau ada beberapa tokoh di layar */
  uid?: string;
}> = ({ pose, mouth, blink, breathe, look, theme, height, prop, antenna, mood = "netral", time = 0, tint, hair = "none", hairColor = "#3d2b1f", uid = "" }) => {
  const robot = look === "robot";
  const c = tint ? { body: tint, body2: shade(tint, 0.35), limb: shade(tint, -0.55) } : theme.char;
  const lift = -pose.jump * 150;
  const squash = 1 + breathe * 0.012;
  const shoulderY = robot ? 330 : 365;
  const eyeY = robot ? 222 : 318;
  const mouthY = robot ? 272 : 386;
  const open = Math.max(mouth, pose.gasp, mood === "kaget" && mouth < 0.1 ? 0.35 : 0);
  const browY = eyeY - 44 - pose.brow * 14 - (mood === "kaget" ? 12 : 0);
  const id = `c${look}${uid}`;
  // Alis per ekspresi: [kiri-luar, kiri-dalam, kanan-dalam, kanan-luar] (offset y; negatif = naik)
  const brows: Record<Mood, [number, number, number, number]> = {
    netral: [pose.brow * 3, -4, -4, pose.brow * 3],
    senang: [-2, -8, -8, -2],
    sedih: [10, -14, -14, 10],
    marah: [-12, 14, 14, -12],
    kaget: [-6, -10, -10, -6],
    bingung: [-14, -10, 6, 8],
    takut: [6, -16, -16, 6],
  };
  const [b1, b2, b3, b4] = brows[mood] ?? brows.netral;
  const eyeScale = mood === "kaget" ? 1.25 : mood === "marah" ? 0.85 : 1;
  return (
    <svg viewBox="0 0 400 620" width={(height * 400) / 620} height={height} style={{ overflow: "visible" }}>
      <defs>
        <linearGradient id={`${id}-body`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor={c.body2} />
          <stop offset="1" stopColor={c.body} />
        </linearGradient>
        <radialGradient id={`${id}-shine`} cx="0.35" cy="0.25" r="0.6">
          <stop offset="0" stopColor="#ffffff" stopOpacity="0.45" />
          <stop offset="1" stopColor="#ffffff" stopOpacity="0" />
        </radialGradient>
      </defs>
      {/* bayangan di lantai mengecil saat melompat */}
      <ellipse cx={200} cy={604} rx={120 * (1 - pose.jump * 0.45)} ry={16 * (1 - pose.jump * 0.4)} fill="#000000" opacity={0.22} />
      <g transform={`translate(0 ${lift})`}>
        {/* kaki */}
        <g transform={`rotate(${pose.leg} 165 500)`}>
          <line x1={165} y1={490} x2={165} y2={578} stroke={c.limb} strokeWidth={30} strokeLinecap="round" />
          <ellipse cx={156} cy={590} rx={34} ry={17} fill={c.limb} />
        </g>
        <g transform={`rotate(${-pose.leg} 235 500)`}>
          <line x1={235} y1={490} x2={235} y2={578} stroke={c.limb} strokeWidth={30} strokeLinecap="round" />
          <ellipse cx={244} cy={590} rx={34} ry={17} fill={c.limb} />
        </g>
        <g transform={`rotate(${pose.tilt} 200 520) translate(200 520) scale(${1 / squash} ${squash}) translate(-200 -520)`}>
          {robot ? (
            <>
              <rect x={82} y={300} width={236} height={210} rx={46} fill={`url(#${id}-body)`} />
              <rect x={150} y={360} width={100} height={70} rx={18} fill="#0f172a" opacity={0.35} />
              <line x1={200} y1={140} x2={200 + antenna * 10} y2={92} stroke={c.limb} strokeWidth={10} strokeLinecap="round" />
              <circle cx={200 + antenna * 10} cy={86} r={16} fill={theme.accent2} style={{ filter: `drop-shadow(0 0 10px ${theme.accent2})` }} />
              <rect x={90} y={135} width={220} height={180} rx={56} fill={`url(#${id}-body)`} />
              <rect x={112} y={162} width={176} height={128} rx={40} fill="#0f172a" />
            </>
          ) : (
            <>
              <path d={`M200 205 C 196 170, 214 150, ${236 + antenna * 8} ${140 - antenna * 4}`} stroke={c.limb} strokeWidth={9} fill="none" strokeLinecap="round" />
              <ellipse cx={244 + antenna * 8} cy={136 - antenna * 4} rx={26} ry={14} fill={theme.accent2} transform={`rotate(-25 ${244 + antenna * 8} ${136 - antenna * 4})`} />
              <ellipse cx={200} cy={360} rx={138} ry={158} fill={`url(#${id}-body)`} />
              <ellipse cx={200} cy={428} rx={82} ry={66} fill="#ffffff" opacity={0.18} />
              <ellipse cx={200} cy={360} rx={138} ry={158} fill={`url(#${id}-shine)`} />
              <ellipse cx={135} cy={372} rx={20} ry={12} fill="#fb7185" opacity={0.4} />
              <ellipse cx={265} cy={372} rx={20} ry={12} fill="#fb7185" opacity={0.4} />
            </>
          )}
          {!robot && <HairShape hair={hair} color={hairColor} />}
          {/* alis */}
          {!robot && (
            <>
              <line x1={140} y1={browY + b1} x2={180} y2={browY + b2} stroke={c.limb} strokeWidth={mood === "marah" ? 11 : 8} strokeLinecap="round" />
              <line x1={220} y1={browY + b3} x2={260} y2={browY + b4} stroke={c.limb} strokeWidth={mood === "marah" ? 11 : 8} strokeLinecap="round" />
            </>
          )}
          <g transform={`translate(160 ${eyeY}) scale(${eyeScale}) translate(-160 ${-eyeY})`}>
            <Eye cx={160} cy={eyeY} open={blink} lookX={pose.lookX} lookY={pose.lookY} robot={robot} glow={theme.accent2} />
          </g>
          <g transform={`translate(240 ${eyeY}) scale(${eyeScale}) translate(-240 ${-eyeY})`}>
            <Eye cx={240} cy={eyeY} open={blink} lookX={pose.lookX} lookY={pose.lookY} robot={robot} glow={theme.accent2} />
          </g>
          {/* mulut: senyum saat diam, terbuka mengikuti suku kata saat bicara */}
          {robot ? (
            <rect x={200 - 34} y={mouthY - 4 - open * 14} width={68} height={8 + open * 28} rx={6} fill={theme.accent2} opacity={0.9} />
          ) : open < 0.08 ? (
            mood === "sedih" ? (
              <path d={`M 172 ${mouthY + 12} Q 200 ${mouthY - 8} 228 ${mouthY + 12}`} stroke="#1f1235" strokeWidth={8} fill="none" strokeLinecap="round" />
            ) : mood === "marah" ? (
              <g>
                <rect x={166} y={mouthY - 6} width={68} height={26} rx={6} fill="#ffffff" stroke="#1f1235" strokeWidth={6} />
                <line x1={166} y1={mouthY + 7} x2={234} y2={mouthY + 7} stroke="#1f1235" strokeWidth={4} />
                {[183, 200, 217].map((x) => <line key={x} x1={x} y1={mouthY - 6} x2={x} y2={mouthY + 20} stroke="#1f1235" strokeWidth={4} />)}
              </g>
            ) : mood === "bingung" || mood === "takut" ? (
              <path d={`M 168 ${mouthY + 2} q 8 -10 16 0 t 16 0 t 16 0 t 16 0`} stroke="#1f1235" strokeWidth={7} fill="none" strokeLinecap="round" />
            ) : (
              <path d={`M ${mood === "senang" ? 164 : 170} ${mouthY - 4} Q 200 ${mouthY + (mood === "senang" ? 34 : 22)} ${mood === "senang" ? 236 : 230} ${mouthY - 4}`} stroke="#1f1235" strokeWidth={8} fill={mood === "senang" ? "#1f1235" : "none"} strokeLinecap="round" />
            )
          ) : (
            <g>
              <ellipse cx={200} cy={mouthY + 6} rx={26 - open * 6} ry={6 + open * 22} fill="#1f1235" />
              <ellipse cx={200} cy={mouthY + 10 + open * 12} rx={14} ry={4 + open * 6} fill="#fb7185" />
            </g>
          )}
          <Arm x={80} y={shoulderY} u={pose.lU} f={pose.lF} side={1} color={c.limb} hand={c.body2} />
          <Arm x={320} y={shoulderY} u={pose.rU} f={pose.rF} side={-1} color={c.limb} hand={c.body2} />
          <MoodFx mood={mood} t={time} robot={robot} />
        </g>
        {prop && (
          <text x={200} y={robot ? 70 : 120} fontSize={64} textAnchor="middle" transform={`translate(0 ${S(breathe * TAU) * 4})`}>
            {prop}
          </text>
        )}
      </g>
    </svg>
  );
};

/** Gelapkan (k<0) / terangkan (k>0) warna hex. */
function shade(hex: string, k: number) {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex);
  if (!m) return hex;
  const n = parseInt(m[1], 16);
  const ch = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => Math.round(k >= 0 ? v + (255 - v) * k : v * (1 + k)));
  return "#" + ch.map((v) => v.toString(16).padStart(2, "0")).join("");
}

/** Rambut di atas kepala (badan bulat, puncak kepala ± y 205). */
const HairShape: React.FC<{ hair: Hair; color: string }> = ({ hair, color }) => {
  const st = { stroke: "#1f1235", strokeWidth: 6, strokeLinejoin: "round" as const };
  switch (hair) {
    case "spiky":
      return <path d="M108 280 L120 220 L150 250 L165 195 L195 240 L215 190 L240 240 L265 200 L275 250 L300 225 L292 285 Q200 225 108 280 z" fill={color} {...st} />;
    case "bun":
