          <path d="M80 300 Q90 205 200 205 Q310 205 320 300 Q260 245 200 250 Q140 245 80 300 z" fill={color} {...st} />
        </g>
      );
    case "long":
      return <path d="M70 420 Q60 210 200 205 Q340 210 330 420 L300 420 Q300 270 200 255 Q100 270 100 420 z" fill={color} {...st} />;
    case "cap":
      return (
        <g>
          <path d="M92 285 Q100 200 200 200 Q300 200 308 285 z" fill={color} {...st} />
          <path d="M290 280 h80 q10 0 6 12 l-6 6 h-90 z" fill={color} {...st} />
        </g>
      );
    default:
      return null;
  }
};

/** Efek ekspresi kartun: air mata, keringat, uap marah, tanda tanya, tanda seru, bintang. */
const MoodFx: React.FC<{ mood: Mood; t: number; robot: boolean }> = ({ mood, t, robot }) => {
  const top = robot ? 120 : 200;
  const bounce = Math.abs(Math.sin(t * 4)) * 10;
  const txt = (s: string, x: number, color: string) => (
    <text x={x} y={top - 30 - bounce} fontSize={110} fontWeight={900} textAnchor="middle" fill={color} stroke="#1f1235" strokeWidth={6} paintOrder="stroke" fontFamily="Arial, sans-serif">
      {s}
    </text>
