  switch (mood) {
    case "sedih": {
      const k = (t * 0.9) % 1;
      return <path d={`M150 ${345 + k * 90} q-14 22 0 30 q14 -8 0 -30 z`} fill="#4cc9f0" stroke="#1f1235" strokeWidth={4} opacity={1 - k * 0.6} />;
    }
    case "takut": {
      const k = (t * 0.7) % 1;
      return (
        <g>
          <path d={`M300 ${250 + k * 70} q-22 34 0 46 q22 -12 0 -46 z`} fill="#90e0ef" stroke="#1f1235" strokeWidth={4} />
          {[0, 1, 2].map((i) => <line key={i} x1={60 - i * 6} y1={300 + i * 40} x2={30 - i * 6} y2={300 + i * 40} stroke="#1f1235" strokeWidth={6} strokeLinecap="round" opacity={0.6 + 0.4 * Math.sin(t * 20 + i)} />)}
        </g>
      );
    }
    case "marah":
      return (
        <g opacity={0.9}>
          {[0, 1].map((i) => {
            const k = (t * 1.2 + i * 0.5) % 1;
            return <circle key={i} cx={i ? 330 : 70} cy={top + 40 - k * 120} r={22 + k * 24} fill="#ffffff" stroke="#1f1235" strokeWidth={4} opacity={1 - k} />;
          })}
          <path d={`M300 ${top + 30} l20 -20 m-20 0 l20 20 m10 -30 l-10 10`} stroke="#e63946" strokeWidth={9} strokeLinecap="round" />
        </g>
      );
    case "kaget":
      return (
        <g>
          {txt("!", 200, "#ffd60a")}
          {[-1, 1].map((d) => [0, 1, 2].map((i) => <line key={`${d}${i}`} x1={200 + d * (150 + i * 8)} y1={top + 20 + i * 40} x2={200 + d * (190 + i * 8)} y2={top + i * 40} stroke="#1f1235" strokeWidth={6} strokeLinecap="round" />))}
        </g>
      );
    case "bingung":
      return txt("?", 270, "#a0c4ff");
    case "senang":
      return (
        <g>
          {[
            [70, top + 20],
            [330, top - 10],
            [300, top + 90],
          ].map(([x, y], i) => {
            const s = 0.6 + 0.4 * Math.abs(Math.sin(t * 3 + i));
            return <path key={i} transform={`translate(${x} ${y}) scale(${s})`} d="M0 -26 L7 -7 L26 0 L7 7 L0 26 L-7 7 L-26 0 L-7 -7 z" fill="#ffd60a" stroke="#1f1235" strokeWidth={4} />;
          })}
        </g>
      );
    default:
      return null;
  }
};

