import { AbsoluteFill, Easing, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { Character, lerpPose, mouthOpen, poseFor, walkPose } from "./Character";
import { layoutFor } from "./layout";
import type { Theme } from "./theme";
import { actionFor, positionFor, sceneAt, sceneStarts, speakSecondsFor, wordTimings } from "./timing";
import type { VideoProps } from "./Video";

const BLEND_S = 0.4; // detik untuk berpindah pose dengan halus
const MOVE_S = 1; // detik untuk berjalan ke posisi baru

/**
 * Karakter TETAP ADA sepanjang video (tidak ikut berganti adegan), jadi terasa seperti animasi,
 * bukan slideshow: berjalan ke posisi adegan berikutnya, berganti gerakan dengan halus, dan
 * mulutnya bergerak mengikuti kata narasi yang sedang diucapkan.
 */
export const CharacterLayer: React.FC<{ video: VideoProps; theme: Theme }> = ({ video, theme }) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const starts = sceneStarts(video.sceneFrames, fps);
  const BLEND = Math.round(BLEND_S * fps);
  const MOVE = Math.round(MOVE_S * fps);
  const n = video.scenes.length;
  if (!n) return null;
  if ((video.cast?.length ?? 0) >= 2) return <EnsembleLayer video={video} theme={theme} />;
  const i = sceneAt(frame, starts);
  const scene = video.scenes[i];
  const local = frame - starts[i];
  const t = local / fps;
  const L = layoutFor(width, height, true, positionFor(scene, i, video));

  // Bicara: kata yang sedang diucapkan → bukaan mulut.
  const speak = speakSecondsFor(video.voiceSeconds?.[i] ?? 0, video.sceneFrames[i] / fps);
  const words = wordTimings(scene, speak);
  const w = words.find((x) => t >= x.s && t < x.e);
  const mouth = w ? mouthOpen(w.w, (t - w.s) / Math.max(0.05, w.e - w.s)) : 0;
  const talking = !!words.length && t >= (words[0]?.s ?? 0) && t <= (words[words.length - 1]?.e ?? 0);

  let pose = poseFor(actionFor(scene, i, n), t, L.dir, talking);
  if (i > 0 && local < BLEND) {
    const prev = video.scenes[i - 1];
    const Lp = layoutFor(width, height, true, positionFor(prev, i - 1, video));
    const prevPose = poseFor(actionFor(prev, i - 1, n), (frame - starts[i - 1]) / fps, Lp.dir, false);
    pose = lerpPose(prevPose, pose, Easing.inOut(Easing.cubic)(local / BLEND));
  }

  // Posisi: masuk dari tepi di awal video, lalu berjalan ke posisi tiap adegan.
  let x = L.char.x;
  let walking = 0;
  let towards = 0;
  if (i === 0) {
    const fromX = L.char.x < width / 2 ? -L.char.h * 0.4 : width + L.char.h * 0.4;
    const k = interpolate(local, [0, MOVE], [0, 1], { extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) });
    x = fromX + (L.char.x - fromX) * k;
    walking = k < 1 ? 1 - k * k : 0;
    towards = Math.sign(L.char.x - fromX);
  } else {
    const Lp = layoutFor(width, height, true, positionFor(video.scenes[i - 1], i - 1, video));
    const dx = L.char.x - Lp.char.x;
    if (Math.abs(dx) > 4) {
      const k = interpolate(local, [0, MOVE], [0, 1], { extrapolateRight: "clamp", easing: Easing.inOut(Easing.sin) });
      x = Lp.char.x + dx * k;
      walking = k < 1 ? Math.sin(k * Math.PI) : 0;
      towards = Math.sign(dx);
    }
  }
  pose = walkPose(pose, (frame / fps) * Math.PI * 4.5, walking, towards);
  const bob = -Math.abs(Math.sin((frame / fps) * Math.PI * 4.5)) * 14 * walking;

  // Kedip tiap ±3,2 detik selama ±0,2 detik.
  const cycle = ((frame / fps + 0.57) % 3.23) / 0.2;
  const blink = cycle < 1 ? Math.abs(cycle - 0.5) * 2 : 1;
  const breathe = Math.sin((frame / fps) * 2.2);
  const antenna = Math.sin((frame / fps) * 3.3) + pose.jump * 1.5;
  const enter = spring({ frame, fps, config: { damping: 14, stiffness: 110 } });
  const h = L.char.h;
  const wPx = (h * 400) / 620;
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <div
        style={{
          position: "absolute",
          left: x - wPx / 2,
          top: L.char.feet - h + bob,
          transform: `scale(${0.85 + 0.15 * enter})`,
          transformOrigin: "50% 100%",
        }}
      >
        <Character
          pose={pose}
          mouth={mouth}
          blink={blink}
          breathe={breathe}
          look={video.cast?.[0]?.look ?? video.character?.look ?? "buddy"}
          theme={theme}
          height={h}
          antenna={antenna}
          mood={scene.mood}
          time={frame / fps}
          tint={video.cast?.[0]?.color}
          hair={video.cast?.[0]?.hair}
          hairColor={video.cast?.[0]?.hairColor}
        />
      </div>
    </AbsoluteFill>
  );
};

/** Posisi panggung untuk k tokoh (proporsi lebar layar). Tegak: di dalam area aman medsos. */
function slots(k: number, portrait: boolean): number[] {
  if (portrait) return k >= 3 ? [0.2, 0.44, 0.68] : [0.26, 0.64];
  return k >= 3 ? [0.14, 0.5, 0.86] : [0.17, 0.83];
}

/**
 * Mode cerita: 2-3 tokoh tampil bersama dan bergantian bicara. Yang bicara memakai gerakan adegan + lip-sync +
 * ekspresi (scene.mood); yang lain diam, menoleh ke pembicara, dengan ekspresi reaksi (scene.reaction).
 */
const EnsembleLayer: React.FC<{ video: VideoProps; theme: Theme }> = ({ video, theme }) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const starts = sceneStarts(video.sceneFrames, fps);
  const cast = (video.cast ?? []).slice(0, 3);
  const i = sceneAt(frame, starts);
  const scene = video.scenes[i];
  const local = frame - starts[i];
  const t = local / fps;
  const n = video.scenes.length;
  const portrait = height > width * 1.2;
  const ids = cast.map((c) => c.id);
  const speaker = scene.speaker && ids.includes(scene.speaker) ? scene.speaker : ids[i % ids.length];
  const stageOf = (sc: typeof scene, sp: string) => {
    const on = (sc.onStage ?? []).filter((x) => ids.includes(x));
    const list = on.length ? on : ids;
    return list.includes(sp) ? list : [...list, sp];
  };
  const onStage = ids.filter((x) => stageOf(scene, speaker).includes(x)); // urutan tetap sesuai daftar tokoh
  const prevStage = i > 0 ? stageOf(video.scenes[i - 1], video.scenes[i - 1].speaker && ids.includes(video.scenes[i - 1].speaker!) ? video.scenes[i - 1].speaker! : ids[(i - 1) % ids.length]) : [];
  const xs = slots(onStage.length, portrait);
  const L = layoutFor(width, height, true, "center");
  const h = (portrait ? L.char.h : height * 0.46) * (onStage.length >= 3 ? 0.88 : 1);
  const feet = portrait ? L.char.feet : height * 0.86;
  const wPx = (h * 400) / 620;

  const speak = speakSecondsFor(video.voiceSeconds?.[i] ?? 0, video.sceneFrames[i] / fps);
  const words = wordTimings(scene, speak);
  const w = words.find((x) => t >= x.s && t < x.e);
  const mouth = w ? mouthOpen(w.w, (t - w.s) / Math.max(0.05, w.e - w.s)) : 0;
  const talking = !!words.length && t >= (words[0]?.s ?? 0) && t <= (words[words.length - 1]?.e ?? 0);
  const spX = xs[onStage.indexOf(speaker)] ?? 0.5;

  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      {onStage.map((id, k) => {
        const m = cast.find((c) => c.id === id)!;
        const x = xs[k] * width;
        const isSp = id === speaker;
        const dir: 1 | -1 = spX * width > x ? 1 : -1;
        let pose = isSp ? poseFor(actionFor(scene, i, n), t, onStage.length > 1 ? (k === 0 ? 1 : -1) : 0, talking) : poseFor("idle", t + k * 0.7, dir, false);
        if (!isSp) pose = { ...pose, lookX: dir * 0.7 };
        const off = k * 1.37;
        const cycle = ((frame / fps + 0.57 + off) % 3.23) / 0.2;
        const blink = cycle < 1 ? Math.abs(cycle - 0.5) * 2 : 1;
        const breathe = Math.sin((frame / fps) * 2.2 + off);
        const enter = prevStage.includes(id) ? 1 : spring({ frame: local, fps, config: { damping: 14, stiffness: 110 } });
        const hop = isSp && talking ? -Math.abs(Math.sin(t * 2.4)) * 6 : 0;
        return (
          <div
            key={id}
            style={{
              position: "absolute",
              left: x - wPx / 2,
              top: feet - h + hop,
              opacity: enter,
              transform: `scale(${0.85 + 0.15 * enter})`,
              transformOrigin: "50% 100%",
            }}
          >
            <Character
              pose={pose}
              mouth={isSp ? mouth : 0}
              blink={blink}
              breathe={breathe}
              look={m.look}
              theme={theme}
              height={h}
              antenna={Math.sin((frame / fps) * 3.3 + off) + pose.jump * 1.5}
              mood={isSp ? scene.mood : scene.reaction}
              time={frame / fps + off}
              tint={m.color}
              hair={m.hair}
              hairColor={m.hairColor}
              uid={id}
            />
            {isSp && m.name && (
              <div style={{ position: "absolute", left: 0, right: 0, top: h * 1.01, textAlign: "center", fontFamily: theme.font, fontWeight: 900, fontSize: h * 0.075, color: theme.text, opacity: 0.9 }}>{m.name}</div>
            )}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

