import { getAudioDurationInSeconds } from "@remotion/media-utils";
import { Composition, staticFile, type CalculateMetadataFunction } from "remotion";
import { SIZES } from "./theme";
import type { VideoData } from "./types";
import { fpsOf, transitionFrames } from "./timing";
import { Video, type VideoProps } from "./Video";
import data from "./video.json";


/** Durasi tiap adegan: dari "seconds", diperpanjang kalau file suara narasi lebih panjang. */
const calculateMetadata: CalculateMetadataFunction<VideoProps> = async ({ props }) => {
  const FPS = fpsOf(props);
  const T = transitionFrames(FPS);
  const voiceSeconds: number[] = [];
  const sceneFrames = await Promise.all(
    props.scenes.map(async (s, i) => {
      let seconds = Math.max(1.5, Number(s.seconds) || 4);
      voiceSeconds[i] = 0;
      if (s.voiceFile) {
        try {
          voiceSeconds[i] = await getAudioDurationInSeconds(staticFile(s.voiceFile));
          seconds = Math.max(seconds, voiceSeconds[i] + 0.6);
        } catch {
          // file suara tidak terbaca: pakai durasi dari storyboard
        }
      }
      return Math.round(seconds * FPS) + T;
    }),
  );
  const total = sceneFrames.reduce((a, b) => a + b, 0) - T * Math.max(0, sceneFrames.length - 1);
  const full = SIZES[props.format] ?? SIZES["9:16"];
  // Mode Adem: 720p (2/3 ukuran). Semua ukuran di animasi mengikuti lebar/tinggi, jadi tampilannya sama.
  const k = props.quality === "720" ? 2 / 3 : 1;
  const size = { width: Math.round(full.width * k), height: Math.round(full.height * k) };
  return { fps: FPS, durationInFrames: Math.max(FPS, total), width: size.width, height: size.height, props: { ...props, sceneFrames, voiceSeconds } };
};

export const Root: React.FC = () => {
  const video = data as VideoData;
  const size = SIZES[video.format] ?? SIZES["9:16"];
  return (
    <Composition
      id="Video"
      component={Video}
      fps={30}
      width={size.width}
      height={size.height}
      durationInFrames={300}
      defaultProps={{ ...video, sceneFrames: [], voiceSeconds: [] }}
      calculateMetadata={calculateMetadata}
    />
  );
};

