import { AbsoluteFill, Easing, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { pop, rise, wordsShown } from "./anim";
import { Elements } from "./Assets";
import type { Box } from "./layout";
import type { Theme } from "./theme";
import type { Scene as SceneData, Word } from "./types";

const norm = (s: string) => s.toLowerCase().replace(/[^\p{L}\p{N}]/gu, "");

/** Detik saat kata pertama poin disebut di narasi (supaya poin muncul pas diucapkan). */
function whenSaid(words: Word[], text: string, after: number) {
  const first = norm(text.split(/\s+/)[0] || "");
  if (!first) return null;
  const hit = words.find((w) => w.s >= after && norm(w.w).startsWith(first.slice(0, Math.max(3, Math.min(first.length, 6)))));
  return hit ? hit.s : null;
}

/** Angka yang menghitung naik, mis. "87%" → 0% … 87%. */
function countUp(stat: string, t: number) {
  // Angka + pemisah ribuan gaya Indonesia (300.000) atau desimal (2,5 / 2.5).
  const m = stat.match(/^(\D*?)(\d[\d.,]*\d|\d)(.*)$/);
  if (!m) return stat;
  const raw = m[2];
  const thousands = /^\d{1,3}([.,]\d{3})+$/.test(raw) && !/^\d{1,3}[.,]\d{3}$/.test(raw.replace(/,/g, "")) ? raw[raw.search(/[.,]/)] : /^\d{1,3}\.\d{3}$/.test(raw) ? "." : "";
  const decSep = thousands ? "" : raw.includes(",") ? "," : raw.includes(".") ? "." : "";
  const target = parseFloat(thousands ? raw.split(thousands).join("") : raw.replace(",", "."));
  const dec = decSep ? (raw.split(decSep)[1] || "").length : 0;
  const v = target * Easing.out(Easing.cubic)(Math.min(1, Math.max(0, (t - 0.2) / 1.4)));
  let txt = v.toFixed(dec);
  if (decSep) txt = txt.replace(".", decSep);
  if (thousands) txt = Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g, thousands);
  return m[1] + txt + m[3];
}

/** Satu adegan, digambar di dalam kotak konten. Semua gerak dari frame (halus, konsisten). */
export const Scene: React.FC<{ scene: SceneData; theme: Theme; index: number; box: Box; stage: Box; ground: Box; words: Word[]; frames: number }> = ({ scene, theme, index, box, stage, ground, words, frames }) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const t = frame / fps;
  const u = Math.min(width, height) / 1080;
  const k = Math.min(1, box.width / (900 * u)); // kecilkan teks kalau kotak sempit
  const full: Box = { left: 0, top: 0, width, height };
  const illus = scene.type === "scene";

  // Konten sedikit naik pelan (kamera utama ada di Camera.tsx).
  const cam = interpolate(frame, [0, frames], [0, 1], { extrapolateRight: "clamp" });

  const titleSize = (illus ? 62 : scene.type === "title" || scene.type === "cta" ? 100 : 80) * u * k;
  const title = (
    <h1 style={{ margin: 0, fontSize: titleSize, lineHeight: 1.08, fontWeight: 800, letterSpacing: -1.5 * u, color: theme.text, textAlign: "center", textShadow: illus ? "0 4px 16px rgba(0,0,0,0.35)" : undefined }}>
      {wordsShown(scene.title, frame, fps, 4, 4).map(({ w, on, age }, i) => (
        <span
          key={i}
          style={{
            display: "inline-block",
            marginRight: "0.25em",
            // Masuk per kata dengan hentakan pegas (membesar → pas, sedikit berputar): lebih "hidup", tetap ringan.
            opacity: on ? Math.min(1, age * 6) : 0,
            transform: (() => {
              const k = on ? spring({ frame: Math.round(age * fps), fps, config: { damping: 11, stiffness: 170, mass: 0.7 } }) : 0;
              return `translateY(${(1 - k) * 40 * u}px) scale(${1.35 - 0.35 * k}) rotate(${(1 - k) * (i % 2 ? 6 : -6)}deg)`;
            })(),
            backgroundImage: i % 3 === 1 ? `linear-gradient(90deg, ${theme.accent}, ${theme.accent2})` : undefined,
            WebkitBackgroundClip: i % 3 === 1 ? "text" : undefined,
            color: i % 3 === 1 ? "transparent" : undefined,
          }}
        >
          {w}
        </span>
      ))}
    </h1>
  );

  const text = scene.text ? (
    <p style={{ ...rise(frame, fps, 14), margin: 0, marginTop: 28 * u, fontSize: 42 * u * k, lineHeight: 1.4, color: theme.muted, textAlign: "center" }}>{scene.text}</p>
  ) : null;

  const floatY = Math.sin(t * 1.6) * 10 * u;
  const emoji = scene.emoji ? (
    <div style={{ ...pop(frame, fps, 2), fontSize: (scene.type === "emoji" ? 280 : 140) * u * k, lineHeight: 1, marginBottom: 34 * u }}>
      <div style={{ transform: `translateY(${floatY}px) rotate(${Math.sin(t * 1.3) * 5}deg)` }}>{scene.emoji}</div>
    </div>
  ) : null;

  let body: React.ReactNode;
  switch (scene.type) {
    case "bullets": {
      const list = scene.bullets ?? [];
      const span = Math.max(1, (words[words.length - 1]?.e ?? frames / fps) - 0.5);
      let after = 0;
      const times = list.map((b, i) => {
        const said = whenSaid(words, b, after);
        const at = said ?? 0.4 + (i * span * 0.8) / Math.max(1, list.length);
        after = at;
        return at;
      });
      body = (
        <>
          {title}
          <div style={{ marginTop: 40 * u, display: "flex", flexDirection: "column", gap: 20 * u, width: "100%" }}>
            {list.map((b, i) => {
              const f = Math.round(times[i] * fps);
              const lit = frame >= f;
              return (
                <div
                  key={i}
                  style={{
                    ...rise(frame, fps, times[i] * 30),
                    display: "flex",
                    alignItems: "center",
                    gap: 24 * u,
                    padding: `${22 * u}px ${30 * u}px`,
                    borderRadius: theme.radius * u,
                    background: theme.card,
                    border: `${2 * u}px solid ${lit ? theme.accent : theme.accent + "30"}`,
                    boxShadow: lit && (times[i + 1] === undefined || frame < times[i + 1] * fps) ? `0 0 ${36 * u}px ${theme.accent}55` : "none",
                    fontSize: 42 * u * k,
                    color: theme.text,
                  }}
                >
                  <span
                    style={{
                      flexShrink: 0,
                      width: 54 * u,
                      height: 54 * u,
                      borderRadius: "50%",
                      display: "grid",
                      placeItems: "center",
                      fontSize: 28 * u,
                      fontWeight: 800,
                      color: "#fff",
                      background: `linear-gradient(135deg, ${theme.accent}, ${theme.accent2})`,
                    }}
                  >
                    {i + 1}
                  </span>
                  {b}
                </div>
              );
            })}
          </div>
        </>
      );
      break;
    }
    case "stat":
      body = (
        <>
          <div
            style={{
              ...pop(frame, fps, 2),
              fontSize: Math.min(230 * u * k, (box.width * 1.35) / Math.max(1, (scene.stat || "").length)),
              fontWeight: 900,
              lineHeight: 1,
              backgroundImage: `linear-gradient(90deg, ${theme.accent}, ${theme.accent2})`,
              WebkitBackgroundClip: "text",
              color: "transparent",
              marginBottom: 26 * u,
            }}
          >
            {countUp(scene.stat || "", t)}
          </div>
          {title}
          {text}
        </>
      );
      break;
    case "quote":
      body = (
        <div style={{ ...rise(frame, fps, 0), padding: 60 * u, borderRadius: theme.radius * u, background: theme.card, borderLeft: `${10 * u}px solid ${theme.accent}` }}>
          <div style={{ fontSize: 150 * u, lineHeight: 0.6, color: theme.accent, fontWeight: 900 }}>“</div>
          {title}
          {text}
        </div>
      );
      break;
    case "cta":
      body = (
        <>
          {emoji}
          {title}
          {text}
          <div
            style={{
              ...pop(frame, fps, 24),
              marginTop: 50 * u,
              padding: `${28 * u}px ${64 * u}px`,
              borderRadius: 999,
              fontSize: 46 * u * k,
              fontWeight: 800,
              color: "#fff",
              background: `linear-gradient(90deg, ${theme.accent}, ${theme.accent2})`,
              boxShadow: `0 0 ${(50 + Math.sin(t * 4) * 20) * u}px ${theme.accent}aa`,
            }}
          >
            {scene.bullets?.[0] ?? "Mulai sekarang"}
