        <div style={{ position: "absolute", top: 0, left: 0, right: 0 }}>
          {title}
          {text}
        </div>
      );
      break;
    default:
      body = (
        <>
          {emoji}
          {title}
          {text}
        </>
      );
  }

  return (
    <AbsoluteFill data-scene={index} style={{ fontFamily: theme.font }}>
      {scene.elements?.length ? <Elements elements={scene.elements} stage={illus ? stage : full} ground={ground} full={full} sceneIndex={index} theme={theme} /> : null}
      <div
        style={{
          position: "absolute",
          left: box.left,
          top: box.top,
          width: box.width,
          height: box.height,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: illus ? "flex-start" : "center",
          transform: `translateY(${-cam * 14 * u}px)`,
        }}
      >
        {body}
      </div>
    </AbsoluteFill>
  );
};

