import { springTiming, TransitionSeries } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { clockWipe } from "@remotion/transitions/clock-wipe";
import { cube } from "@remotion/transitions/cube";
import { flip } from "@remotion/transitions/flip";
import { pushCut } from "@remotion/transitions/push-cut";
import { slide } from "@remotion/transitions/slide";
import { wipe } from "@remotion/transitions/wipe";
import { AbsoluteFill, Audio, interpolate, staticFile, useCurrentFrame, useVideoConfig } from "remotion";
import { Background } from "./Background";
import { Backdrop } from "./Backdrops";
import { CameraRig } from "./Camera";
import { Captions } from "./Captions";
import { CharacterLayer } from "./CharacterLayer";
import { layoutFor } from "./layout";
import { Scene } from "./Scene";
import { THEMES } from "./theme";
import { positionFor, speakSecondsFor, transitionFrames, wordTimings } from "./timing";
import type { Scene as SceneData, VideoData } from "./types";


/**
 * Transisi bervariasi supaya terasa seperti video animasi, bukan slideshow — semuanya ringan
 * (hanya transform/clip, TANPA blur: blur membuat render 2x lebih berat).
 * Angka & kejutan → hentakan (push-cut + kilat), penutup → balik (flip), lainnya bergiliran.
 */
const transitionAt = (i: number, fps: number, next: SceneData | undefined, width: number, height: number) => {
  const timing = springTiming({ config: { damping: 200 }, durationInFrames: transitionFrames(fps) });
  const key = `t${i}`;
  if (next?.type === "stat" || next?.action === "surprised")
    return <TransitionSeries.Transition key={key} presentation={pushCut({ flashColor: "#ffffff", flashOpacity: 0.3 })} timing={timing} />;
  if (next?.type === "cta") return <TransitionSeries.Transition key={key} presentation={flip({ direction: "from-bottom" })} timing={timing} />;
  switch (i % 6) {
    case 1:
      return <TransitionSeries.Transition key={key} presentation={cube({ direction: "from-right" })} timing={timing} />;
    case 2:
      return <TransitionSeries.Transition key={key} presentation={wipe({ direction: "from-top-left" })} timing={timing} />;
    case 3:
      return <TransitionSeries.Transition key={key} presentation={slide({ direction: "from-bottom" })} timing={timing} />;
    case 4:
      return <TransitionSeries.Transition key={key} presentation={clockWipe({ width, height })} timing={timing} />;
    default:
      return <TransitionSeries.Transition key={key} presentation={fade()} timing={timing} />;
  }
};

const Progress: React.FC<{ color: string }> = ({ color }) => {
  const frame = useCurrentFrame();
  const { durationInFrames, width, height } = useVideoConfig();
  const u = Math.min(width, height) / 1080;
  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        height: 8 * u,
        width: `${interpolate(frame, [0, durationInFrames - 1], [0, 100], { extrapolateRight: "clamp" })}%`,
        background: color,
      }}
    />
  );
};

export type VideoProps = VideoData & { sceneFrames: number[]; voiceSeconds?: number[] };

/** Nada suara (semitone) → toneFrequency Remotion (0.5..2). Default: laki-laki -4, perempuan +2. */
export function pitchOf(v: VideoData["voice"]) {
  const def = v?.gender === "male" ? -4 : 2;
  const st = Math.max(-12, Math.min(12, Number.isFinite(v?.pitch) ? Number(v?.pitch) : def));
  return Math.pow(2, st / 12);
}

/**
 * Lapisan video (dari belakang ke depan):
 * latar bergerak → adegan (teks + elemen animasi, dengan transisi) → karakter (tetap ada sepanjang video)
 * → subtitle karaoke → progress bar. Audio narasi per adegan.
 */
export const Video: React.FC<VideoProps> = (props) => {
  const { width, height, fps } = useVideoConfig();
  const theme = THEMES[props.style] ?? THEMES.neon;
  const showChar = props.character?.show !== false;
  const tone = pitchOf(props.voice);
  return (
    <AbsoluteFill>
      <CameraRig video={props} depth={0.45} bleed>
        <Background theme={theme} />
      </CameraRig>
      <CameraRig video={props}>
        <TransitionSeries>
          {props.scenes.flatMap((scene, i) => {
            const frames = props.sceneFrames[i];
            const L = layoutFor(width, height, showChar, positionFor(scene, i, props));
            const words = wordTimings(scene, speakSecondsFor(props.voiceSeconds?.[i] ?? 0, frames / fps));
            // Panggung ilustrasi selebar layar dibagi dua supaya benda tidak tertutup subtitle:
            // "langit" (bawah judul → atas subtitle) dan "tanah" (bawah subtitle → pijakan kaki karakter).
            const portrait = height > width * 1.2;
            const top = L.content.top + height * (portrait ? 0.07 : 0.13);
            const feet = showChar ? L.char.feet : height * 0.8;
            const skyBottom = portrait ? L.captions.top - height * 0.01 : Math.min(L.captions.top, height * 0.7);
            const stage = { left: 0, top, width, height: Math.max(height * 0.15, skyBottom - top) };
            const groundTop = portrait ? L.captions.top + L.captions.height : height * 0.55;
            const ground = { left: 0, top: groundTop, width, height: Math.max(height * 0.1, feet + height * 0.01 - groundTop) };
            const items = [
              <TransitionSeries.Sequence key={`s${i}`} durationInFrames={frames}>
                {scene.background ? <Backdrop id={scene.background} theme={theme} /> : null}
                <Scene scene={scene} theme={theme} index={i} box={L.content} stage={stage} ground={ground} words={words} frames={frames} />
                {scene.voiceFile ? <Audio src={staticFile(scene.voiceFile)} toneFrequency={Math.abs(tone - 1) > 0.001 ? tone : undefined} /> : null}
              </TransitionSeries.Sequence>,
            ];
            if (i < props.scenes.length - 1) items.push(transitionAt(i, fps, props.scenes[i + 1], width, height));
            return items;
          })}
        </TransitionSeries>
        {showChar ? <CharacterLayer video={props} theme={theme} /> : null}
      </CameraRig>
      {props.captions ? <Captions video={props} theme={theme} /> : null}
      <Progress color={theme.accent2} />
    </AbsoluteFill>
  );
};

