import { interpolate, spring } from "remotion";

// Semua jeda di sini ditulis dalam "frame pada 30 fps" lalu diskalakan ke fps video,
// supaya tempo animasi sama di 24, 30, maupun 60 fps.
const at = (frames30: number, fps: number) => (frames30 * fps) / 30;

/** Muncul dengan pegas: naik + memudar masuk. */
export function rise(frame: number, fps: number, delay = 0) {
  const s = spring({ frame: frame - at(delay, fps), fps, config: { damping: 14, stiffness: 120, mass: 0.6 } });
  return {
    opacity: interpolate(s, [0, 1], [0, 1]),
    transform: `translateY(${interpolate(s, [0, 1], [60, 0])}px) scale(${interpolate(s, [0, 1], [0.92, 1])})`,
  };
}

/** Membesar dari kecil dengan sedikit pantulan. */
export function pop(frame: number, fps: number, delay = 0) {
  const s = spring({ frame: frame - at(delay, fps), fps, config: { damping: 9, stiffness: 140 } });
  return { opacity: Math.min(1, s * 1.5), transform: `scale(${s})` };
}

/** Teks muncul per kata. */
export function wordsShown(text: string, frame: number, fps: number, start = 0, perWord = 3) {
  const words = text.split(/\s+/).filter(Boolean);
  const s0 = at(start, fps);
  const per = at(perWord, fps);
  const n = Math.floor(Math.max(0, frame - s0) / per) + 1;
  return words.map((w, i) => ({ w, on: i < n, age: (frame - s0 - i * per) / fps }));
}

