import type { CharacterPosition } from "./types";

export type Box = { left: number; top: number; width: number; height: number };
export type Layout = {
  content: Box;
  captions: Box;
  /** Titik tengah kaki karakter + tinggi karakter (px) */
  char: { x: number; feet: number; h: number };
  /** Arah konten dilihat dari karakter: 1 kanan, -1 kiri, 0 atas */
  dir: 1 | -1 | 0;
};

/** Pembagian layar: karakter di satu sisi, konten di sisi lain, subtitle di bawah. */
export function layoutFor(width: number, height: number, showChar: boolean, position: CharacterPosition): Layout {
  const portrait = height > width * 1.2;
  if (portrait) {
    // Area aman TikTok/Reels/Shorts: ±20% bawah (keterangan & musik) dan sisi kanan (tombol like/komentar)
    // tertutup tampilan aplikasi, jadi teks, subtitle, dan karakter dijaga di luar area itu.
    const x = position === "left" ? 0.27 : position === "right" ? 0.63 : 0.45;
    return showChar
      ? {
          content: { left: width * 0.06, top: height * 0.085, width: width * 0.8, height: height * 0.36 },
          captions: { left: width * 0.05, top: height * 0.455, width: width * 0.82, height: height * 0.09 },
          char: { x: width * x, feet: height * 0.8, h: height * 0.26 },
          dir: 0,
        }
      : {
          content: { left: width * 0.06, top: height * 0.1, width: width * 0.8, height: height * 0.5 },
          captions: { left: width * 0.05, top: height * 0.63, width: width * 0.82, height: height * 0.11 },
          char: { x: width * x, feet: height * 0.8, h: height * 0.26 },
          dir: 0,
        };
  }
  const square = !(width > height * 1.2);
  const left = position === "left";
  const charW = square ? 0.36 : 0.34;
  const cw = 1 - charW - 0.08;
  if (!showChar) {
    return {
      content: { left: width * 0.08, top: height * 0.1, width: width * 0.84, height: height * 0.64 },
      captions: { left: width * 0.08, top: height * 0.78, width: width * 0.84, height: height * 0.16 },
      char: { x: width * 0.8, feet: height * 0.88, h: height * 0.6 },
      dir: -1,
    };
  }
  const contentLeft = left ? width * (charW + 0.03) : width * 0.05;
  return {
    content: { left: contentLeft, top: height * 0.08, width: width * cw, height: height * (square ? 0.62 : 0.66) },
    captions: { left: contentLeft, top: height * (square ? 0.74 : 0.78), width: width * cw, height: height * 0.18 },
    char: { x: width * (left ? charW / 2 + 0.01 : 1 - charW / 2 - 0.01), feet: height * 0.9, h: height * (square ? 0.56 : 0.68) },
    dir: left ? 1 : -1,
  };
}

