import type { CharacterAction, CharacterPosition, Scene, VideoData, Word } from "./types";

/** Lama transisi antar adegan: 0,5 detik (dalam frame, mengikuti fps). */
export const transitionFrames = (fps: number) => Math.round(fps / 2);

/** FPS yang didukung. 60 fps = 2x lebih berat & lama dirender dari 30 fps. */
export const fpsOf = (v: { fps?: number }) => (v.fps === 24 || v.fps === 60 ? v.fps : 30);

/** Frame awal tiap adegan (adegan bertumpuk selama transisi). */
export function sceneStarts(sceneFrames: number[], fps: number) {
  const starts: number[] = [];
  let at = 0;
  for (const f of sceneFrames) {
    starts.push(at);
    at += f - transitionFrames(fps);
  }
  return starts;
}

/** Adegan yang sedang tampil di frame ini (yang paling baru mulai). */
export function sceneAt(frame: number, starts: number[]) {
  let i = 0;
  for (let k = 0; k < starts.length; k++) if (frame >= starts[k]) i = k;
  return i;
}

/**
 * Waktu tiap kata narasi (detik dari awal adegan).
 * Pakai waktu asli dari suara AI (scene.words) kalau ada; kalau tidak, diperkirakan dari panjang kata.
 */
export function wordTimings(scene: Scene, speakSeconds: number): Word[] {
  const text = (scene.narration || "").trim();
  if (!text) return [];
  if (scene.words?.length) return scene.words;
  const words = text.split(/\s+/).filter(Boolean);
  const start = 0.25;
  const end = Math.max(start + 0.5, speakSeconds);
  const weight = (w: string) => w.replace(/[^\p{L}\p{N}]/gu, "").length + 2 + (/[.,!?;:]$/.test(w) ? 3 : 0);
  const total = words.reduce((a, w) => a + weight(w), 0);
  let t = start;
  return words.map((w) => {
    const d = ((end - start) * weight(w)) / total;
    const out = { w, s: t, e: t + d * (/[.,!?;:]$/.test(w) ? 0.7 : 0.92) };
    t += d;
    return out;
  });
}

/** Lama bicara di adegan: panjang suara AI, atau ±90% durasi adegan kalau tanpa suara. */
export const speakSecondsFor = (voiceSeconds: number, sceneSeconds: number) => (voiceSeconds > 0 ? voiceSeconds : Math.max(0.8, sceneSeconds * 0.9 - 0.4));

export function actionFor(scene: Scene, i: number, n: number): CharacterAction {
  if (scene.action) return scene.action;
  if (i === 0) return "wave";
  if (scene.type === "cta" || i === n - 1) return "celebrate";
  if (scene.type === "bullets" || scene.type === "stat") return "present";
  if (scene.type === "quote") return "think";
  return scene.narration ? "talk" : "idle";
}

export function positionFor(scene: Scene, i: number, video: VideoData): CharacterPosition {
  if (scene.position) return scene.position;
  if (video.format === "9:16") return i % 2 === 0 ? "center" : i % 4 === 1 ? "left" : "right";
  return i % 2 === 0 ? "left" : "right";
}

files.src/types.ts:
// Bentuk data storyboard di src/video.json. Edit video.json untuk mengubah isi video.
// HARUS sama dengan lib/video.ts di aplikasi PRD Generator.
/** "scene" = adegan ilustrasi: elemen animasi jadi tokoh utama, judul kecil di atas. */
export type SceneType = "title" | "text" | "bullets" | "stat" | "quote" | "emoji" | "cta" | "scene";

/** Gerakan karakter di adegan ini. */
export type CharacterAction = "talk" | "wave" | "point" | "present" | "think" | "surprised" | "celebrate" | "idle";
/** Posisi karakter. Konten (teks) otomatis menempati sisi lain. */
export type CharacterPosition = "left" | "right" | "center";

/** Gerak kamera adegan. "auto" = dipilih otomatis sesuai jenis adegan. */
export type CameraMove =
  | "auto"
  | "static"
  | "zoom-in"
  | "zoom-out"
  | "punch-in" // zoom cepat menghentak
  | "pan-left"
  | "pan-right"
  | "pan-up"
  | "pan-down"
  | "shake" // getar
  | "handheld" // goyang halus seperti kamera dipegang
  | "dutch" // miring pelan
  | "whip" // sapuan cepat masuk dari samping
  | "orbit" // mengitari sedikit
  | "focus-character" // zoom ke karakter
  | "bounce"; // memantul berirama

/** Waktu tiap kata narasi (detik dari awal adegan). Diisi scripts/voice.mjs dari suara AI. */
export type Word = { w: string; s: number; e: number };

/** Pola gerak elemen animasi. */
export type Motion =
  | "fall" // jatuh melayang lalu mendarat (daun)
  | "rain" // jatuh terus-menerus (hujan, tetes air)
  | "rise" // naik terus lalu hilang (gelembung, uap, nutrisi)
  | "float" // melayang di tempat
  | "drift" // bergeser pelan melintasi layar (awan)
  | "fly" // terbang melintas dengan lengkung (burung, serangga)
  | "crawl" // merayap di dasar area (cacing, semut)
  | "swim" // berenang bolak-balik (ikan, bakteri)
  | "orbit" // berputar mengelilingi pusat
  | "grow" // tumbuh dari bawah (tunas, pohon)
  | "pop" // muncul memantul
  | "spin" // berputar
  | "pulse" // berdenyut
  | "wiggle" // bergoyang di tempat (bakteri, jamur)
  | "bounce" // memantul naik turun
  | "shrink" // mengecil & memudar: membusuk/terurai
  | "dash" // melesat cepat menyeberang layar (cahaya, roket, komet)
  | "fill"; // khusus soil/water: lapisan naik terisi

/**
 * Elemen animasi di adegan. asset = id dari pustaka (lihat src/Assets.tsx: leaf, dryleaf, bacteria,
 * fungi, worm, drop, cloud, sun, sprout, tree, rock, seed, bubble, dot, sparkle, arrow, gear, heart,
 * soil, water) ATAU satu emoji apa pun (mis. "🐜", "🐞", "🦔").
 */
export type SceneElement = {
  asset: string;
  motion?: Motion;
  /** Jumlah salinan (1-30) */
  count?: number;
  /** Tempat di panggung */
  area?: "full" | "top" | "middle" | "bottom" | "left" | "right" | "center";
  size?: "s" | "m" | "l" | "xl";
  /** Mulai setelah berapa detik dari awal adegan (supaya muncul pas disebut narasi) */
  delay?: number;
  /** Warna (hanya untuk aset pustaka), mis. "#b45309" */
  color?: string;
  /** Keterangan kecil di bawah area elemen */
  label?: string;
};

export type Scene = {
  type: SceneType;
  /** Judul / teks utama adegan */
  title: string;
  /** Teks pendukung */
  text?: string;
  /** Poin-poin (untuk type "bullets"), atau [label tombol] untuk "cta" */
  bullets?: string[];
  /** Emoji besar (untuk type "emoji"), juga hiasan/benda yang dipegang karakter */
  emoji?: string;
  /** Angka besar (untuk type "stat"), mis. "87%". Angkanya dianimasikan menghitung naik. */
  stat?: string;
  /** Naskah narasi: dibacakan suara AI, jadi subtitle karaoke, dan menggerakkan mulut karakter */
  narration?: string;
  /** Durasi adegan (detik). Kalau suara narasi lebih panjang, durasi ikut suara. */
  seconds: number;
  /** Gerakan karakter (default: talk kalau ada narasi) */
  action?: CharacterAction;
  /** Gerak kamera (default: otomatis bervariasi) */
  camera?: CameraMove;
  /** Posisi karakter (default: bergantian kiri/kanan) */
  position?: CharacterPosition;
  /** Elemen animasi (daun jatuh, bakteri, cacing, air, tanah, emoji apa pun, ...) */
  elements?: SceneElement[];
  /** Latar ruangan kartun (lihat src/Backdrops.tsx). Kosong = latar tema biasa. */
  background?: Backdrop;
  /** Ekspresi tokoh yang bicara: senang, sedih, marah, kaget, bingung, takut, netral */
  mood?: Mood;
  /** Mode cerita: id tokoh (dari VideoData.cast) yang bicara di adegan ini */
  speaker?: string;
  /** Mode cerita: id tokoh yang tampil di adegan ini (bawaan: semua tokoh) */
  onStage?: string[];
  /** Ekspresi tokoh lain yang mendengarkan */
  reaction?: Mood;
  /** Diisi otomatis oleh scripts/voice.mjs */
  voiceFile?: string;
  /** Diisi otomatis oleh scripts/voice.mjs (waktu kata asli dari suara AI) */
  words?: Word[];
};

export type CharacterLook = "buddy" | "robot";

/** Latar ruangan kartun. */
export type Backdrop = "kamar" | "dapur" | "lab" | "bengkel" | "kantor" | "kelas" | "taman" | "jalan" | "angkasa";
/** Ekspresi wajah (efek kartun: keringat, alis, mulut, simbol di atas kepala). */
export type Mood = "netral" | "senang" | "sedih" | "marah" | "kaget" | "bingung" | "takut";
/** Gaya rambut tokoh. */
export type Hair = "none" | "spiky" | "bun" | "long" | "cap";
/** Tokoh di mode cerita (2-3 tokoh bergantian bicara). */
export type CastMember = { id: string; name: string; look: CharacterLook; color: string; hair: Hair; hairColor?: string };

export type VideoData = {
  title: string;
  /** Rasio: 9:16 (Reels/TikTok/Shorts), 16:9 (YouTube), 1:1 (feed) */
  format: "9:16" | "16:9" | "1:1";
  /** Gaya visual */
  style: "neon" | "clean" | "kids" | "corporate";
  /** Subtitle karaoke dari narasi */
  captions: boolean;
  /** Resolusi render: "1080" (bawaan) atau "720" (mode Adem, jauh lebih ringan) */
  quality?: "720" | "1080";
  /** Frame per detik: 24, 30 (bawaan), atau 60 (lebih halus tapi 2x lebih berat dirender) */
  fps?: 24 | 30 | 60;
  /**
   * Suara narasi. engine: piper (bawaan, gratis, offline) | elevenlabs | openai | none.
   * gender: male/female. pitch: nada dalam semitone (laki-laki -6..-2, perempuan 0..+6), diterapkan saat render.
   */
  voice?: { engine?: "piper" | "elevenlabs" | "openai" | "none"; gender?: "male" | "female"; pitch?: number; lang?: string };
  /** Karakter animasi pembawa acara */
  character?: { show: boolean; look: CharacterLook };
  /** Mode cerita: 2-3 tokoh (kalau ada ≥ 2, semua tampil di panggung & bergantian bicara) */
  cast?: CastMember[];
  /** Gaya subtitle: "karaoke" (baris, bawaan) atau "kata" (satu kata besar di tengah, gaya video cerita) */
  captionStyle?: "karaoke" | "kata";
  scenes: Scene[];
};
